/**
 * ImageEditFormContext
 *
 * Form state for image editing: prompts, strengths, LoRA, model selection,
 * advanced settings, number of generations, variant toggle.
 *
 * Consumer: EditModePanel (only).
 * Split from ImageEditContext to avoid re-renders of canvas/overlay components
 * when the user is typing prompts or adjusting form controls.
 */

import React, { createContext, useContext } from 'react';
import type {
  LoraMode,
  QwenEditModel,
  EditAdvancedSettings,
} from '../model/editSettingsTypes';
import { DEFAULT_ADVANCED_SETTINGS } from '../model/editSettingsTypes';

export type { LoraMode };

// ============================================================================
// Types
// ============================================================================

export interface ImageEditFormState {
  inpaintPrompt: string;
  setInpaintPrompt: (value: string) => void;
  inpaintNumGenerations: number;
  setInpaintNumGenerations: (value: number) => void;
  flushTextFields: () => Promise<void>;
  img2imgPrompt: string;
  setImg2imgPrompt: (value: string) => void;
  img2imgStrength: number;
  setImg2imgStrength: (value: number) => void;
  enablePromptExpansion: boolean;
  setEnablePromptExpansion: (value: boolean) => void;
  loraMode: LoraMode;
  setLoraMode: (mode: LoraMode) => void;
  customLoraUrl: string;
  setCustomLoraUrl: (url: string) => void;
  createAsGeneration: boolean;
  setCreateAsGeneration: (value: boolean) => void;
  qwenEditModel: QwenEditModel;
  setQwenEditModel: (model: QwenEditModel) => void;
  advancedSettings: EditAdvancedSettings;
  setAdvancedSettings: (settings: EditAdvancedSettings) => void;
}

// ============================================================================
// Defaults
// ============================================================================

const EMPTY_FORM: ImageEditFormState = {
  inpaintPrompt: '',
  setInpaintPrompt: () => {},
  inpaintNumGenerations: 1,
  setInpaintNumGenerations: () => {},
  flushTextFields: async () => {},
  img2imgPrompt: '',
  setImg2imgPrompt: () => {},
  img2imgStrength: 0.6,
  setImg2imgStrength: () => {},
  enablePromptExpansion: false,
  setEnablePromptExpansion: () => {},
  loraMode: 'none',
  setLoraMode: () => {},
  customLoraUrl: '',
  setCustomLoraUrl: () => {},
  createAsGeneration: false,
  setCreateAsGeneration: () => {},
  qwenEditModel: 'qwen-edit-2511',
  setQwenEditModel: () => {},
  advancedSettings: DEFAULT_ADVANCED_SETTINGS,
  setAdvancedSettings: () => {},
};

// ============================================================================
// Context + Hook
// ============================================================================

const ImageEditFormContext = createContext<ImageEditFormState | null>(null);

interface ImageEditFormProviderProps {
  children: React.ReactNode;
  value: ImageEditFormState;
}

export const ImageEditFormProvider: React.FC<ImageEditFormProviderProps> = ({
  children,
  value,
}) => {
  return (
    <ImageEditFormContext.Provider value={value}>
      {children}
    </ImageEditFormContext.Provider>
  );
};

/**
 * Returns form edit state and fails loudly when the provider is missing.
 */
export function useImageEditForm(): ImageEditFormState {
  const context = useContext(ImageEditFormContext);
  if (!context) {
    throw new Error('useImageEditForm must be used within an ImageEditFormProvider');
  }
  return context;
}

/**
 * Returns form edit state, or safe defaults when missing a provider on purpose.
 */
export function useImageEditFormSafe(): ImageEditFormState {
  const context = useContext(ImageEditFormContext);
  return context ?? EMPTY_FORM;
}

import React from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/components/ui/tabs";

import { useExtraLargeModal } from '@/shared/hooks/useModal';
import { useScrollFade } from '@/shared/hooks/useScrollFade';
import { useListResources, useCreateResource, useUpdateResource, useDeleteResource } from '@/features/resources/hooks/useResources';
import { useUserUIState } from '@/shared/hooks/useUserUIState';

import { LoraSelectorModalProps } from './types';
import { CommunityLorasTab } from './components/CommunityLorasTab';
import { MyLorasTab } from './components/MyLorasTab/MyLorasTab';
import { LoraSelectorFooter } from './components/LoraSelectorFooter';
import { useLoraFilters } from './hooks/useLoraFilters';

export const LoraSelectorModal: React.FC<LoraSelectorModalProps> = ({
  isOpen,
  onClose,
  loras,
  onAddLora,
  onRemoveLora,
  onUpdateLoraStrength,
  selectedLoras,
  loraType,
}) => {
  const myLorasResource = useListResources('lora');
  const createResource = useCreateResource();
  const updateResource = useUpdateResource();
  const deleteResource = useDeleteResource();

  // Privacy defaults for new LoRAs
  const { value: privacyDefaults } = useUserUIState('privacyDefaults', { resourcesPublic: true, generationsPublic: false });

  const {
    activeTab,
    setActiveTab,
    editingLora,
    handleEdit,
    clearEdit,
    switchToBrowse,
    showMyLorasOnly,
    setShowMyLorasOnly,
    showAddedLorasOnly,
    setShowAddedLorasOnly,
    filteredLoraCount,
    setFilteredLoraCount,
    selectedModelFilter,
    setSelectedModelFilter,
    selectedSubFilter,
    setSelectedSubFilter,
    currentPage,
    totalPages,
    onPageChange,
    handlePageChange,
  } = useLoraFilters(loraType);

  // Modal styling and scroll fade
  const modal = useExtraLargeModal('loraSelector');
  const { showFade, scrollRef } = useScrollFade({
    isOpen: isOpen,
    debug: false,
    preloadFade: modal.isMobile
  });
  const modalHeaderPaddingClass = modal.isMobile ? 'px-2 pt-1 pb-2' : 'px-6 pt-2 pb-2';
  const modalTabRowPaddingClass = `${modal.isMobile ? 'px-2' : 'px-6'} py-2 flex-shrink-0`;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      {isOpen && (
        <DialogContent
          className={modal.className}
          style={modal.style}
        >
          <div className={modal.headerClass}>
            <DialogHeader className={`${modalHeaderPaddingClass} flex-shrink-0`}>
              <DialogTitle>LoRA Library</DialogTitle>
            </DialogHeader>
          </div>
          <div
            ref={scrollRef}
            className={modal.scrollClass}
          >
            <div className={modalTabRowPaddingClass}>
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full flex flex-col flex-1 overflow-hidden">
                <TabsList className="grid w-full grid-cols-2 mb-2">
                  <TabsTrigger value="browse" className="w-full">Browse LoRAs</TabsTrigger>
                  <TabsTrigger value="add-new" className="w-full">Add LoRA</TabsTrigger>
                </TabsList>
              </Tabs>
            </div>

            {/* Tab Content */}
            <div className="flex-1 flex flex-col min-h-0">
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full flex flex-col flex-1 overflow-hidden">
                <TabsContent value="browse" className="flex-1 flex flex-col min-h-0">
                  <CommunityLorasTab
                    loras={loras}
                    onAddLora={onAddLora}
                    onRemoveLora={onRemoveLora}
                    onUpdateLoraStrength={onUpdateLoraStrength}
                    selectedLoras={selectedLoras}
                    myLorasResource={myLorasResource}
                    createResource={createResource}
                    updateResource={updateResource}
                    deleteResource={deleteResource}
                    onClose={onClose}
                    onEdit={handleEdit}
                    showMyLorasOnly={showMyLorasOnly}
                    setShowMyLorasOnly={setShowMyLorasOnly}
                    showAddedLorasOnly={showAddedLorasOnly}
                    setShowAddedLorasOnly={setShowAddedLorasOnly}
                    onProcessedLorasLengthChange={setFilteredLoraCount}
                    onPageChange={handlePageChange}
                    selectedModelFilter={selectedModelFilter}
                    setSelectedModelFilter={setSelectedModelFilter}
                    selectedSubFilter={selectedSubFilter}
                    setSelectedSubFilter={setSelectedSubFilter}
                  />
                </TabsContent>
                <TabsContent value="add-new" className="flex-1 min-h-0 overflow-auto">
                  <MyLorasTab
                    myLorasResource={myLorasResource}
                    deleteResource={deleteResource}
                    createResource={createResource}
                    updateResource={updateResource}
                    onSwitchToBrowse={switchToBrowse}
                    editingLora={editingLora}
                    onClearEdit={clearEdit}
                    defaultIsPublic={privacyDefaults.resourcesPublic}
                  />
                </TabsContent>
              </Tabs>
            </div>
          </div>

          {/* Control Panel Footer - Always sticks to bottom like PromptEditorModal */}
          {activeTab === 'browse' && (
            <LoraSelectorFooter
              footerClass={modal.footerClass}
              isMobile={modal.isMobile}
              showFade={showFade}
              showAddedLorasOnly={showAddedLorasOnly}
              setShowAddedLorasOnly={setShowAddedLorasOnly}
              showMyLorasOnly={showMyLorasOnly}
              setShowMyLorasOnly={setShowMyLorasOnly}
              filteredLoraCount={filteredLoraCount}
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={onPageChange}
              onClose={onClose}
            />
          )}
        </DialogContent>
      )}
    </Dialog>
  );
};

import React from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/shared/components/ui/dialog';
import { Button } from '@/shared/components/ui/button';
import { useExtraLargeModal } from '@/shared/hooks/useModal';
import { useScrollFade } from '@/shared/hooks/useScrollFade';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/components/ui/tabs';
import {
  useListResources,
  useListPublicResources,
  useCreateResource,
  useUpdateResource,
  useDeleteResource,
} from '@/features/resources/hooks/useResources';
import { Checkbox } from '@/shared/components/ui/checkbox';
import { useUserUIState } from '@/shared/hooks/useUserUIState';
import { SelectorModalFooterFrame } from '@/shared/components/modal/SelectorModalFooterFrame';
import { BrowsePresetsTab } from './components/BrowsePresetsTab';
import { AddNewPresetTab } from './components/AddNewPresetTab';
import { usePhaseConfigSelectorModalState } from './hooks/usePhaseConfigSelectorModalState';
import type { PhaseConfigSelectorModalProps } from './types';

export const PhaseConfigSelectorModal: React.FC<PhaseConfigSelectorModalProps> = ({
  isOpen,
  onClose,
  onSelectPreset,
  onRemovePreset,
  selectedPresetId,
  currentPhaseConfig,
  initialTab = 'browse',
  currentSettings,
  intent = 'load',
  availableLoras = [],
  generationTypeMode = 'i2v',
}) => {
  const myPresetsResource = useListResources('phase-config');
  const publicPresetsResource = useListPublicResources('phase-config');
  const createResource = useCreateResource();
  const updateResource = useUpdateResource();
  const deleteResource = useDeleteResource();

  const { value: privacyDefaults } = useUserUIState('privacyDefaults', {
    resourcesPublic: true,
    generationsPublic: false,
  });

  const {
    state,
    setActiveTab,
    handleEdit,
    handleOverwrite,
    handleClearEdit,
    handleSwitchToBrowse,
    toggleShowMyPresetsOnly,
    toggleShowSelectedPresetOnly,
    setProcessedPresetsLength,
    handlePageChange,
  } = usePhaseConfigSelectorModalState({
    isOpen,
    initialTab,
    intent,
  });

  const {
    activeTab,
    editingPreset,
    isOverwriting,
    showMyPresetsOnly,
    showSelectedPresetOnly,
    processedPresetsLength,
    currentPage,
    totalPages,
    onPageChange,
  } = state;

  const modal = useExtraLargeModal('phaseConfigSelector');
  const { showFade, scrollRef } = useScrollFade({
    isOpen,
    debug: false,
    preloadFade: modal.isMobile,
  });

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      {isOpen && (
        <DialogContent className={modal.className} style={modal.style}>
          <div className={modal.headerClass}>
            <DialogHeader className={`${modal.isMobile ? 'px-2 pt-1 pb-2' : 'px-6 pt-2 pb-2'} flex-shrink-0`}>
              <DialogTitle>Phase Config Presets</DialogTitle>
              <DialogDescription>Save and reuse advanced phase configurations</DialogDescription>
            </DialogHeader>
          </div>

          <div ref={scrollRef} className={modal.scrollClass}>
            <div className={`${modal.isMobile ? 'px-2' : 'px-6'} py-2 flex-shrink-0`}>
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full flex flex-col flex-1 overflow-hidden">
                <TabsList className="grid w-full grid-cols-2 mb-2">
                  <TabsTrigger value="browse" className="w-full">Browse Presets</TabsTrigger>
                  <TabsTrigger value="add-new" className="w-full">Add New Preset</TabsTrigger>
                </TabsList>
              </Tabs>
            </div>

            <div className="flex-1 flex flex-col min-h-0">
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full flex flex-col flex-1 overflow-hidden">
                <TabsContent value="browse" className="flex-1 flex flex-col min-h-0">
                  <BrowsePresetsTab
                    onSelectPreset={onSelectPreset}
                    onRemovePreset={onRemovePreset}
                    selectedPresetId={selectedPresetId}
                    myPresetsResource={myPresetsResource}
                    publicPresetsResource={publicPresetsResource}
                    createResource={createResource}
                    deleteResource={deleteResource}
                    onEdit={handleEdit}
                    intent={intent}
                    onOverwrite={handleOverwrite}
                    showMyPresetsOnly={showMyPresetsOnly}
                    showSelectedPresetOnly={showSelectedPresetOnly}
                    onProcessedPresetsLengthChange={setProcessedPresetsLength}
                    onPageChange={handlePageChange}
                    initialModelTypeFilter={generationTypeMode || 'all'}
                  />
                </TabsContent>

                <TabsContent value="add-new" className="flex-1 min-h-0 overflow-auto">
                  <AddNewPresetTab
                    createResource={createResource}
                    updateResource={updateResource}
                    onSwitchToBrowse={handleSwitchToBrowse}
                    currentPhaseConfig={currentPhaseConfig}
                    editingPreset={editingPreset}
                    onClearEdit={handleClearEdit}
                    currentSettings={currentSettings}
                    isOverwriting={isOverwriting}
                    availableLoras={availableLoras}
                    generationTypeMode={generationTypeMode}
                    defaultIsPublic={privacyDefaults.resourcesPublic}
                  />
                </TabsContent>
              </Tabs>
            </div>
          </div>

          {activeTab === 'browse' && (
            <SelectorModalFooterFrame
              footerClass={modal.footerClass}
              isMobile={modal.isMobile}
              showFade={showFade}
              summary={
                showMyPresetsOnly && showSelectedPresetOnly
                  ? `${processedPresetsLength} selected`
                  : showMyPresetsOnly
                    ? `${processedPresetsLength} yours`
                    : showSelectedPresetOnly
                      ? `${processedPresetsLength} selected`
                      : `${processedPresetsLength} total`
              }
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={onPageChange}
              onClose={onClose}
              controls={
                <>
                    <Button
                      variant={showSelectedPresetOnly ? 'default' : 'outline'}
                      size="sm"
                      onClick={toggleShowSelectedPresetOnly}
                      className="flex items-center gap-2"
                      disabled={!selectedPresetId}
                    >
                      <Checkbox checked={showSelectedPresetOnly} className="pointer-events-none h-4 w-4" />
                      <span className="hidden sm:inline">Show selected preset</span>
                      <span className="sm:hidden">Selected</span>
                    </Button>

                    <Button
                      variant={showMyPresetsOnly ? 'default' : 'outline'}
                      size="sm"
                      onClick={toggleShowMyPresetsOnly}
                      className="flex items-center gap-2"
                    >
                      <Checkbox checked={showMyPresetsOnly} className="pointer-events-none h-4 w-4" />
                      <span className="hidden sm:inline">Show my presets</span>
                      <span className="sm:hidden">My Presets</span>
                    </Button>
                </>
              }
            />
          )}
        </DialogContent>
      )}
    </Dialog>
  );
};

/*
 * Keep `<Dialog open={...}>` mounted until `open` flips false.
 * Base UI releases focus scope and body pointer-events during close, not on unmount.
 * Returning `null` above an open dialog can strand the page in a blocked state.
 * If closed-state children are expensive, gate `<DialogContent>` instead.
 */

import * as React from "react"
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog"
import { X } from "lucide-react"
import { cn } from "@/shared/components/ui/contracts/cn"

const Dialog = DialogPrimitive.Root

const DialogTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Trigger> & { asChild?: boolean }
>(({ asChild, children, ...props }, ref) => {
  if (asChild) {
    return <DialogPrimitive.Trigger ref={ref} render={React.Children.only(children) as React.ReactElement} {...props} />
  }
  return <DialogPrimitive.Trigger ref={ref} {...props}>{children}</DialogPrimitive.Trigger>
})
DialogTrigger.displayName = "DialogTrigger"

const DialogPortal = DialogPrimitive.Portal

const DialogOverlay = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Backdrop>
>(({ className, onClick, ...props }, ref) => (
  <DialogPrimitive.Backdrop
    ref={ref}
    data-dialog-backdrop
    className={cn(
      "fixed inset-0 z-[100002] bg-black/80 cursor-pointer data-[open]:animate-in data-[ending-style]:animate-out data-[ending-style]:fade-out-0 data-[open]:fade-in-0",
      className
    )}
    onClick={onClick}
    {...props}
  />
))
DialogOverlay.displayName = "DialogOverlay"

const DialogContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Popup>
>(({ className, children, ...props }, ref) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Popup
      data-pane-control
      data-dialog-content
      ref={ref}
      className={cn(
        "fixed left-[50%] top-[50%] z-[100003] grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[open]:animate-in data-[ending-style]:animate-out data-[ending-style]:fade-out-0 data-[open]:fade-in-0 data-[ending-style]:zoom-out-95 data-[open]:zoom-in-95 data-[ending-style]:slide-out-to-left-1/2 data-[ending-style]:slide-out-to-top-[48%] data-[open]:slide-in-from-left-1/2 data-[open]:slide-in-from-top-[48%] sm:rounded-lg",
        className
      )}
      {...props}
    >
      {children}
      <DialogPrimitive.Close data-dialog-close className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[open]:bg-accent data-[open]:text-muted-foreground">
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </DialogPrimitive.Close>
    </DialogPrimitive.Popup>
  </DialogPortal>
))
DialogContent.displayName = "DialogContent"

const DialogHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col gap-y-1.5 text-center sm:text-left",
      className
    )}
    {...props}
  />
)
DialogHeader.displayName = "DialogHeader"

const DialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col-reverse sm:flex-row sm:justify-end sm:gap-x-2",
      className
    )}
    {...props}
  />
)
DialogFooter.displayName = "DialogFooter"

const DialogTitle = React.forwardRef<
  HTMLHeadingElement,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    className={cn(
      "text-lg font-light leading-none tracking-tight",
      className
    )}
    {...props}
  />
))
DialogTitle.displayName = "DialogTitle"

const DialogDescription = React.forwardRef<
  HTMLParagraphElement,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
))
DialogDescription.displayName = "DialogDescription"

export {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
}

/**
 * ImageEditContext Tests
 *
 * Tests for the composed image edit context provider and backward-compatible hook.
 */

import { describe, it, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';

import {
  ImageEditProvider,
  useImageEditCanvasSafe,
  useImageEditForm,
  useImageEditFormSafe,
  useImageEditStatusSafe,
} from '../ImageEditContext';

describe('ImageEditContext', () => {
  describe('safe hooks outside provider', () => {
    it('useImageEditCanvasSafe returns defaults', () => {
      function Consumer() {
        const canvas = useImageEditCanvasSafe();
        return (
          <div>
            <span data-testid="isInpaintMode">{String(canvas.isInpaintMode)}</span>
            <span data-testid="isMagicEditMode">{String(canvas.isMagicEditMode)}</span>
            <span data-testid="brushSize">{canvas.brushSize}</span>
            <span data-testid="editMode">{String(canvas.editMode)}</span>
          </div>
        );
      }

      render(<Consumer />);

      expect(screen.getByTestId('isInpaintMode')).toHaveTextContent('false');
      expect(screen.getByTestId('isMagicEditMode')).toHaveTextContent('false');
      expect(screen.getByTestId('editMode')).toHaveTextContent('null');
    });

    it('useImageEditFormSafe returns defaults', () => {
      function Consumer() {
        // This test intentionally omits the provider to verify the explicit Safe fallback.
        const form = useImageEditFormSafe();
        return (
          <div>
            <span data-testid="inpaintPrompt">{form.inpaintPrompt || 'empty'}</span>
            <span data-testid="img2imgStrength">{form.img2imgStrength}</span>
            <span data-testid="enablePromptExpansion">{String(form.enablePromptExpansion)}</span>
          </div>
        );
      }

      render(<Consumer />);

      expect(screen.getByTestId('inpaintPrompt')).toHaveTextContent('empty');
    });

    it('useImageEditForm throws outside provider', () => {
      function Consumer() {
        useImageEditForm();
        return null;
      }

      const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
      expect(() => render(<Consumer />)).toThrow(
        'useImageEditForm must be used within an ImageEditFormProvider'
      );
      consoleError.mockRestore();
    });

    it('useImageEditStatusSafe returns defaults', () => {
      function Consumer() {
        const status = useImageEditStatusSafe();
        return (
          <div>
            <span data-testid="isGeneratingInpaint">{String(status.isGeneratingInpaint)}</span>
            <span data-testid="isGeneratingImg2Img">{String(status.isGeneratingImg2Img)}</span>
            <span data-testid="isSavingAsVariant">{String(status.isSavingAsVariant)}</span>
          </div>
        );
      }

      render(<Consumer />);

      expect(screen.getByTestId('isGeneratingInpaint')).toHaveTextContent('false');
      expect(screen.getByTestId('isGeneratingImg2Img')).toHaveTextContent('false');
      expect(screen.getByTestId('isSavingAsVariant')).toHaveTextContent('false');
    });
  });

  describe('ImageEditProvider', () => {
    // Build a minimal mock state for the composed provider
    const mockState = {
      // Canvas state
      isInpaintMode: true,
      isMagicEditMode: false,
      isSpecialEditMode: true,
      editMode: 'inpaint' as const,
      setIsInpaintMode: vi.fn(),
      setIsMagicEditMode: vi.fn(),
      setEditMode: vi.fn(),
      handleEnterInpaintMode: vi.fn(),
      handleExitInpaintMode: vi.fn(),
      handleEnterMagicEditMode: vi.fn(),
      handleExitMagicEditMode: vi.fn(),
      brushSize: 20,
      setBrushSize: vi.fn(),
      isEraseMode: false,
      setIsEraseMode: vi.fn(),
      brushStrokes: [],
      handleUndo: vi.fn(),
      handleClearMask: vi.fn(),
      toolPanelPosition: 'bottom' as const,
      setToolPanelPosition: vi.fn(),
      isAnnotateMode: false,
      setIsAnnotateMode: vi.fn(),
      annotationMode: 'rectangle' as const,
      setAnnotationMode: vi.fn(),
      selectedShapeId: null,
      onStrokeComplete: vi.fn(),
      onStrokesChange: vi.fn(),
      onSelectionChange: vi.fn(),
      onTextModeHint: vi.fn(),
      strokeOverlayRef: { current: null },
      getDeleteButtonPosition: vi.fn(),
      handleToggleFreeForm: vi.fn(),
      handleDeleteSelected: vi.fn(),
      repositionTransform: { x: 0, y: 0, scale: 1, rotation: 0, flipH: false, flipV: false },
      hasTransformChanges: false,
      isRepositionDragging: false,
      repositionDragHandlers: {},
      getTransformStyle: vi.fn(),
      setScale: vi.fn(),
      setRotation: vi.fn(),
      toggleFlipH: vi.fn(),
      toggleFlipV: vi.fn(),
      resetTransform: vi.fn(),
      imageContainerRef: { current: null },
      isFlippedHorizontally: false,
      isSaving: false,
      // Form state
