import { useEffect, useMemo, useState } from 'react';
import type { Resource } from '@/features/resources/hooks/useResources';
import type { LoraModel, ModelFilterCategory } from '@/domains/lora/components/LoraSelectorModal/types';
import {
  getDefaultSubFilter,
  getFilterCategory,
  getSubFilterOptions,
} from '@/domains/lora/components/LoraSelectorModal/utils/filter-utils';

type EditableLora = Resource & { metadata: LoraModel };

export function useLoraFilters(loraType: unknown) {
  const [showMyLorasOnly, setShowMyLorasOnly] = useState(false);
  const [showAddedLorasOnly, setShowAddedLorasOnly] = useState(false);
  const [filteredLoraCount, setFilteredLoraCount] = useState(0);

  const [selectedModelFilter, setSelectedModelFilter] =
    useState<ModelFilterCategory>(() => getFilterCategory(loraType));
  const [selectedSubFilter, setSelectedSubFilter] = useState<string>(() =>
    getDefaultSubFilter(loraType)
  );

  useEffect(() => {
    setSelectedModelFilter(getFilterCategory(loraType));
    setSelectedSubFilter(getDefaultSubFilter(loraType));
  }, [loraType]);

  const validSubOptions = useMemo(
    () => getSubFilterOptions(selectedModelFilter).map((option) => option.value),
    [selectedModelFilter]
  );

  useEffect(() => {
    if (!validSubOptions.includes(selectedSubFilter)) {
      setSelectedSubFilter('all');
    }
  }, [selectedSubFilter, validSubOptions]);

  const [currentPage, setCurrentPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [onPageChange, setOnPageChange] = useState<((page: number) => void) | null>(
    null
  );

  const handlePageChange = (
    page: number,
    total: number,
    setPage: (page: number) => void
  ) => {
    setCurrentPage(page);
    setTotalPages(total);
    setOnPageChange(() => setPage);
  };

  // Tab & editing state (was useLoraEditing)
  const [activeTab, setActiveTab] = useState<string>('browse');
  const [editingLora, setEditingLora] = useState<EditableLora | null>(null);

  const handleEdit = (lora: EditableLora) => {
    setEditingLora(lora);
    setActiveTab('add-new');
  };

  const clearEdit = () => {
    setEditingLora(null);
  };

  const switchToBrowse = () => {
    setActiveTab('browse');
    clearEdit();
  };

  return {
    showMyLorasOnly,
    setShowMyLorasOnly,
    showAddedLorasOnly,
    setShowAddedLorasOnly,
    filteredLoraCount,
    setFilteredLoraCount,
    selectedModelFilter,
    setSelectedModelFilter,
    selectedSubFilter,
    setSelectedSubFilter,
    currentPage,
    totalPages,
    onPageChange,
    handlePageChange,
    activeTab,
    setActiveTab,
    editingLora,
    handleEdit,
    clearEdit,
    switchToBrowse,
  };
}

import { useIsMobile } from "@/shared/hooks/mobile";
import { safeAreaCalc } from "@/shared/lib/safeArea";

export type ModalSize = 'small' | 'medium' | 'large' | 'extra-large';

interface ModalStyling {
  className: string;
  style: Record<string, unknown>;
  isMobile: boolean;
  headerClass: string;
  scrollClass: string;
  footerClass: string;
}

/**
 * Simplified modal hook that replaces the complex useMobileModalStyling system
 * Provides the same functionality with much less complexity
 */
export const useModal = (size: ModalSize = 'medium'): ModalStyling => {
  const isMobile = useIsMobile();

  // Base classes that all modals need - removed z-index from classes since we apply it via inline style
  const baseClasses = 'bg-white dark:bg-gray-950 border-gray-200 dark:border-gray-800 rounded-lg flex flex-col';

  // Size-specific max widths and heights
  const sizeClasses = {
    small: 'sm:max-w-sm',
    medium: 'sm:max-w-[425px] max-h-[85vh]', 
    large: 'sm:max-w-2xl max-h-[90vh]',
    'extra-large': 'max-w-4xl max-h-[90vh]'
  }[size];

  // Mobile-specific styles (only for medium and larger modals)
  // Note: z-index is handled by the Dialog component CSS (z-[100003]) so we don't override it here
  const mobileStyle = isMobile && size !== 'small' ? {
    width: 'calc(100vw - 2rem)', // 16px edges
    maxHeight: (size === 'large' || size === 'extra-large')
      ? safeAreaCalc.maxHeight('80px', '80vh')
      : safeAreaCalc.maxHeight('64px', '90vh'),
    // Position modal lower on mobile to account for safe area at top
    top: (size === 'large' || size === 'extra-large')
      ? safeAreaCalc.verticalCenter()
      : undefined,
  } : {};

  return {
    className: `${sizeClasses} ${baseClasses}`,
    style: mobileStyle,
    isMobile,
    headerClass: 'flex-shrink-0',
    scrollClass: 'flex-1 overflow-y-auto min-h-0',
    footerClass: 'flex-shrink-0'
  };
};

// Convenience functions for common sizes
export const useMediumModal = () => useModal('medium');
export const useLargeModal = () => useModal('large');
export const useExtraLargeModal = (_specialCase?: string) => {
  // For now, ignore specialCase - the old system had 'promptEditor' and 'loraSelector' but they don't seem to do much
  return useModal('extra-large');
};

import { useState, useEffect, useRef } from 'react';

interface UseScrollFadeOptions {
  /** Whether the modal is open (to trigger re-checks) */
  isOpen?: boolean;
  /** Threshold in pixels from bottom to consider "scrolled to bottom" */
  bottomThreshold?: number;
  /** Whether to enable debug logging */
  debug?: boolean;
  /** Show fade immediately when opened, then adjust based on content */
  preloadFade?: boolean;
}

interface UseScrollFadeReturn {
  /** Whether to show the fade overlay */
  showFade: boolean;
  /** Ref to attach to the scrollable container */
  scrollRef: React.RefObject<HTMLDivElement>;
}

/**
 * Hook for smart scroll-aware fade effect that appears above footer borders
 * Only shows when content is scrollable and user hasn't reached the bottom
 */
export const useScrollFade = ({
  isOpen = true,
  bottomThreshold = 5,
  debug = false,
  preloadFade = false
}: UseScrollFadeOptions = {}): UseScrollFadeReturn => {
  const [showFade, setShowFade] = useState(preloadFade && isOpen);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // If preloadFade is enabled, show fade immediately when opening
    if (preloadFade && isOpen) {
      setShowFade(true);
    }

    // Reduced delay for faster response, but still ensure DOM is ready
    const timer = setTimeout(() => {
      const container = scrollRef.current;
      if (!container) {
        return;
      }

    const checkScroll = () => {
      const { scrollTop, scrollHeight, clientHeight } = container;
      const isScrolledToBottom = scrollTop + clientHeight >= scrollHeight - bottomThreshold;
      const hasScrollableContent = scrollHeight > clientHeight;

      // Only show fade when:
      // 1. Content is scrollable (overflows container)
      // 2. User hasn't reached the bottom
      const shouldShowFade = hasScrollableContent && !isScrolledToBottom;

      setShowFade(shouldShowFade);
    };

    // Initial check
    checkScroll();

    // Check on scroll
    container.addEventListener('scroll', checkScroll, { passive: true });

    // Check when container size changes
    const resizeObserver = new ResizeObserver(() => {
      // Use setTimeout to ensure layout is complete
      setTimeout(checkScroll, 0);
    });
    resizeObserver.observe(container);

    // Check when content changes (dynamic loading, etc.)
    const mutationObserver = new MutationObserver(() => {
      setTimeout(checkScroll, 0);
    });
    mutationObserver.observe(container, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: false
    });

      return () => {
        container.removeEventListener('scroll', checkScroll);
        resizeObserver.disconnect();
        mutationObserver.disconnect();
      };
    }, 50); // Reduced delay from 100ms to 50ms for faster response

    return () => {
      clearTimeout(timer);
    };
  }, [isOpen, bottomThreshold, debug, preloadFade]);


  return {
    showFade,
    scrollRef
  };
};

