/**
 * LightboxStateContext
 *
 * Provides shared state to deeply-nested lightbox components without prop drilling.
 * Organized into logical domains accessible via focused hooks:
 * - useLightboxCore() - onClose, readOnly, isMobile, selectedProjectId
 * - useLightboxMedia() - media, isVideo, effectiveUrls, dimensions
 * - useLightboxVariants() - variants, activeVariant, variant actions
 * - useLightboxNavigation() - navigation state and handlers
 *
 * Components should prefer these hooks over prop drilling for commonly-used values.
 */

import React, { createContext, useContext, RefObject } from 'react';
import type { GenerationRow } from '@/domains/generation/types';
import type { GenerationVariant } from '@/shared/hooks/variants/useVariants';
import type { CurrentSegmentImagesData } from '@/shared/components/VariantSelector/variantSourceImages';

// ============================================================================
// Core State
// ============================================================================

interface LightboxCoreState {
  onClose: () => void;
  readOnly: boolean;
  isMobile: boolean;
  isTabletOrLarger: boolean;
  selectedProjectId: string | null;
  actualGenerationId: string | null;
}

// ============================================================================
// Media State
// ============================================================================

interface LightboxMediaState {
  media: GenerationRow;
  isVideo: boolean;
  effectiveMediaUrl: string;
  effectiveVideoUrl: string;
  effectiveImageDimensions: { width: number; height: number } | null;
  imageDimensions: { width: number; height: number } | null;
  setImageDimensions: (dims: { width: number; height: number }) => void;
}

// ============================================================================
// Variant State
// ============================================================================

interface LightboxVariantState {
  variants: GenerationVariant[];
  activeVariant: GenerationVariant | null;
  primaryVariant: GenerationVariant | null;
  isLoadingVariants: boolean;
  // Handler-style names for UI components
  handleVariantSelect: (id: string) => void;
  handleMakePrimary: (id: string) => Promise<void>;
  handleDeleteVariant: (id: string) => Promise<void>;
  onLoadVariantSettings?: (variantParams: Record<string, unknown>) => void;
  onLoadVariantImages?: (variant: GenerationVariant) => void;
  currentSegmentImages?: CurrentSegmentImagesData;
  // Promotion
  promoteSuccess: boolean;
  isPromoting: boolean;
  handlePromoteToGeneration: (variantId: string) => Promise<void>;
  // Make main variant
  isMakingMainVariant: boolean;
  canMakeMainVariant: boolean;
  handleMakeMainVariant: () => Promise<void>;
  // Pending/unviewed counts
  pendingTaskCount: number;
  unviewedVariantCount: number;
  onMarkAllViewed: () => void;
  variantsSectionRef: RefObject<HTMLDivElement> | null;
}

// ============================================================================
// Navigation State
// ============================================================================

interface LightboxNavigationState {
  showNavigation: boolean;
  hasNext: boolean;
  hasPrevious: boolean;
  handleSlotNavNext: () => void;
  handleSlotNavPrev: () => void;
  swipeNavigation: {
    swipeHandlers: Record<string, unknown>;
    isSwiping: boolean;
    swipeOffset: number;
  };
}

// ============================================================================
// Combined Context Value
// ============================================================================

interface LightboxStateValue {
  core: LightboxCoreState;
  media: LightboxMediaState;
  variants: LightboxVariantState;
  navigation: LightboxNavigationState;
}

const LightboxStateContext = createContext<LightboxStateValue | null>(null);

// ============================================================================
// Provider Component
// ============================================================================

interface LightboxStateProviderProps {
  children: React.ReactNode;
  value: LightboxStateValue;
}

export const LightboxStateProvider: React.FC<LightboxStateProviderProps> = ({
  children,
  value,
}) => {
  return (
    <LightboxStateContext.Provider value={value}>
      {children}
    </LightboxStateContext.Provider>
  );
};

// ============================================================================
// Consumer Hooks - Safe versions only (return defaults outside provider)
// ============================================================================

// Note: Non-safe versions (useLightboxState, useLightboxCore, etc.) are not
// exported as they are not used. All internal consumers use the Safe versions
// for safe operation outside the provider.

// ============================================================================
// Safe Hooks (for use outside provider - returns defaults)
// ============================================================================

const EMPTY_CORE: LightboxCoreState = {
  onClose: () => {},
  readOnly: true,
  isMobile: false,
  isTabletOrLarger: true,
  selectedProjectId: null,
  actualGenerationId: null,
};

const EMPTY_MEDIA: LightboxMediaState = {
  media: {} as GenerationRow,
  isVideo: false,
  effectiveMediaUrl: '',
  effectiveVideoUrl: '',
  effectiveImageDimensions: null,
  imageDimensions: null,
  setImageDimensions: () => {},
};

const EMPTY_VARIANTS: LightboxVariantState = {
  variants: [],
  activeVariant: null,
  primaryVariant: null,
  isLoadingVariants: false,
  handleVariantSelect: () => {},
  handleMakePrimary: async () => {},
  handleDeleteVariant: async () => {},
  onLoadVariantSettings: undefined,
  onLoadVariantImages: undefined,
  currentSegmentImages: undefined,
  promoteSuccess: false,
  isPromoting: false,
  handlePromoteToGeneration: async () => {},
  isMakingMainVariant: false,
  canMakeMainVariant: false,
  handleMakeMainVariant: async () => {},
  pendingTaskCount: 0,
  unviewedVariantCount: 0,
  onMarkAllViewed: () => {},
  variantsSectionRef: null,
};

const EMPTY_NAVIGATION: LightboxNavigationState = {
  showNavigation: false,
  hasNext: false,
  hasPrevious: false,
  handleSlotNavNext: () => {},
  handleSlotNavPrev: () => {},
  swipeNavigation: {
    swipeHandlers: {},
    isSwiping: false,
    swipeOffset: 0,
  },
};

/**
 * Safe version of useLightboxCore that returns defaults when used outside provider.
 * Use this in components that may render outside the lightbox context.
 */
export function useLightboxCoreSafe(): LightboxCoreState {
  const context = useContext(LightboxStateContext);
  return context?.core ?? EMPTY_CORE;
}

/**
 * Safe version of useLightboxMedia that returns defaults when used outside provider.
 */
export function useLightboxMediaSafe(): LightboxMediaState {
  const context = useContext(LightboxStateContext);
  return context?.media ?? EMPTY_MEDIA;
}

/**
 * Safe version of useLightboxVariants that returns defaults when used outside provider.
 */
export function useLightboxVariantsSafe(): LightboxVariantState {
  const context = useContext(LightboxStateContext);
  return context?.variants ?? EMPTY_VARIANTS;
}

/**
 * Safe version of useLightboxNavigation that returns defaults when used outside provider.
 */
export function useLightboxNavigationSafe(): LightboxNavigationState {
  const context = useContext(LightboxStateContext);
  return context?.navigation ?? EMPTY_NAVIGATION;
}

// ============================================================================
// Export Types
// ============================================================================

export type {
  LightboxStateValue,
  LightboxCoreState,
  LightboxVariantState,
};

// Note: Default export removed as it was not used externally.

import React from 'react';
import { LightboxStateProvider, type LightboxStateValue } from '../contexts/LightboxStateContext';

interface LightboxProvidersProps {
  stateValue: LightboxStateValue;
  children: React.ReactNode;
}

export function LightboxProviders({
  stateValue,
  children,
}: LightboxProvidersProps) {
  return (
    <LightboxStateProvider value={stateValue}>
      {children}
    </LightboxStateProvider>
  );
}

/** View-model state for EditModePanel. */

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Paintbrush, Pencil, Type, Move, Wand2, ArrowUp } from 'lucide-react';
import React from 'react';
import type {
  EditModePanelCoreState,
  EditModePanelImageEditState,
  EditModePanelVariantsState,
} from '../components/types';

interface UseEditModePanelStateParams {
  variant: 'desktop' | 'mobile';
  currentMediaId: string;

  isCloudMode?: boolean;
  handleUpscale?: () => Promise<void>;

  coreState: EditModePanelCoreState;
  imageEditState: EditModePanelImageEditState;
  variantsState: EditModePanelVariantsState;
}

export interface ModeSelectorItem {
  id: string;
  label: string;
  icon: ReactNode;
  onClick: () => void;
}

export function useEditModePanelState({
  variant,
  currentMediaId,
  isCloudMode,
  handleUpscale,
  coreState,
  imageEditState,
  variantsState,
}: UseEditModePanelStateParams) {
  const isMobile = variant === 'mobile';
  const { onClose } = coreState;

  const {
    editMode,
    setEditMode,
    setIsInpaintMode,
    brushStrokes,
    handleExitMagicEditMode,
    hasTransformChanges,
  } = imageEditState;

  const {
    inpaintPrompt,
    setInpaintPrompt,
    inpaintNumGenerations,
    setInpaintNumGenerations,
    flushTextFields,
    loraMode,
    setLoraMode,
    customLoraUrl,
    setCustomLoraUrl,
    createAsGeneration,
    setCreateAsGeneration,
    img2imgPrompt,
    setImg2imgPrompt,
    img2imgStrength,
    setImg2imgStrength,
    setEnablePromptExpansion,
    qwenEditModel,
    setQwenEditModel,
  } = imageEditState;

  const {
    isGeneratingReposition,
    repositionGenerateSuccess,
    isSavingAsVariant,
    saveAsVariantSuccess,
    isGeneratingInpaint,
    inpaintGenerateSuccess,
    isCreatingMagicEditTasks,
    magicEditTasksCreated,
    isGeneratingImg2Img,
    img2imgGenerateSuccess,
  } = imageEditState;

  const {
    variants,
    activeVariant,
    handleVariantSelect: onVariantSelect,
    handleMakePrimary: onMakePrimary,
    isLoadingVariants = false,
    handlePromoteToGeneration: onPromoteToGeneration,
    isPromoting = false,
    handleDeleteVariant: onDeleteVariant,
    onLoadVariantSettings,
    pendingTaskCount = 0,
    unviewedVariantCount = 0,
    onMarkAllViewed,
    onLoadVariantImages,
    currentSegmentImages,
  } = variantsState;

  const activeVariantId = activeVariant?.id || null;
  const prevEditModeRef = useRef(editMode);
  const [hasUserEditedPrompt, setHasUserEditedPrompt] = useState(false);
  const prevMediaIdRef = useRef(currentMediaId);
  useEffect(() => {
    if (currentMediaId !== prevMediaIdRef.current) {
      setHasUserEditedPrompt(false);
      prevMediaIdRef.current = currentMediaId;
    }
  }, [currentMediaId]);

  useEffect(() => {
    const prevMode = prevEditModeRef.current;
    if (prevMode !== editMode && (editMode === 'inpaint' || editMode === 'annotate')) {
      setLoraMode('none');
    }
    prevEditModeRef.current = editMode;
  }, [editMode, setLoraMode]);

  useEffect(() => {
    if (!isCloudMode && qwenEditModel?.startsWith('flux-klein-')) {
      setQwenEditModel('qwen-edit');
    }
  }, [isCloudMode, qwenEditModel, setQwenEditModel]);

  const handleClearLora = (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoraMode('none');
  };

  const modeSelectorItems: ModeSelectorItem[] = [
    {
      id: 'text',
      label: 'Text',
      icon: React.createElement(Type),
      onClick: () => { setIsInpaintMode(true); setEditMode('text'); },
    },
    {
      id: 'inpaint',
      label: 'Paint',
      icon: React.createElement(Paintbrush),
      onClick: () => { setIsInpaintMode(true); setEditMode('inpaint'); },
    },
    {
      id: 'annotate',
      label: 'Annotate',
      icon: React.createElement(Pencil),
      onClick: () => { setIsInpaintMode(true); setEditMode('annotate'); },
    },
    {
      id: 'reposition',
      label: 'Move',
      icon: React.createElement(Move),
      onClick: () => { setIsInpaintMode(true); setEditMode('reposition'); },
    },
    {
      id: 'img2img',
      label: 'Img2Img',
      icon: React.createElement(Wand2),
      onClick: () => { setIsInpaintMode(true); setEditMode('img2img'); },
    },
    ...(isCloudMode && handleUpscale ? [{
      id: 'upscale',
      label: 'Enhance',
      icon: React.createElement(ArrowUp),
      onClick: () => { setIsInpaintMode(false); setEditMode('upscale'); },
    }] : []),
  ];

  const labelSize = isMobile ? 'text-[10px] uppercase tracking-wide text-muted-foreground' : 'text-sm';
  const textareaMinHeight = isMobile ? 'min-h-[50px]' : 'min-h-[100px]';
  const textareaRows = isMobile ? 2 : 4;
  const textareaPadding = isMobile ? 'px-2 py-1.5' : 'px-3 py-2';
  const textareaTextSize = isMobile ? 'text-base' : 'text-sm'; // 16px on mobile prevents iOS zoom
  const generationsSpacing = isMobile ? 'space-y-0.5' : 'space-y-2';

  return {
    isMobile,
    onClose,
    editMode,
    setEditMode,
    setIsInpaintMode,
    brushStrokes,
    handleExitMagicEditMode,
    hasTransformChanges,
    inpaintPrompt,
    setInpaintPrompt,
    inpaintNumGenerations,
    setInpaintNumGenerations,
    flushTextFields,
    loraMode,
    setLoraMode,
    customLoraUrl,
    setCustomLoraUrl,
    createAsGeneration,
    setCreateAsGeneration,
    img2imgPrompt,
    setImg2imgPrompt,
    img2imgStrength,
    setImg2imgStrength,
    setEnablePromptExpansion,
    qwenEditModel,
    setQwenEditModel,
    isGeneratingReposition,
    repositionGenerateSuccess,
    isSavingAsVariant,
    saveAsVariantSuccess,
    isGeneratingInpaint,
    inpaintGenerateSuccess,
    isCreatingMagicEditTasks,
    magicEditTasksCreated,
    isGeneratingImg2Img,
    img2imgGenerateSuccess,
    variants,
    activeVariantId,
    onVariantSelect,
    onMakePrimary,
    isLoadingVariants,
    onPromoteToGeneration,
    isPromoting,
    onDeleteVariant,
    onLoadVariantSettings,
    pendingTaskCount,
    unviewedVariantCount,
    onMarkAllViewed,
    onLoadVariantImages,
    currentSegmentImages,
    hasUserEditedPrompt,
    setHasUserEditedPrompt,
    handleClearLora,
    modeSelectorItems,
    labelSize,
    textareaMinHeight,
    textareaRows,
    textareaPadding,
    textareaTextSize,
    generationsSpacing,
  };
}

export type EditModePanelState = ReturnType<typeof useEditModePanelState>;

import type { LoraModel } from '@/domains/lora/types/lora';
import type { LoraManagerState } from '@/domains/lora/types/loraManager';
import type { EditAdvancedSettings as EditAdvancedSettingsType } from '../hooks/useGenerationEditSettings';
