/**
 * EditPanelLayout Component
 *
 * Shared layout for edit panels (images and videos).
 * Provides consistent header, mode selector, scrollable content area, and variants section.
 */

import React, { useRef } from 'react';
import { cn } from '@/shared/components/ui/contracts/cn';
import { SegmentedControl, SegmentedControlItem } from '@/shared/components/ui/segmented-control';
import { VariantSelector } from '@/shared/components/VariantSelector';
import type { GenerationVariant } from '@/shared/hooks/variants/useVariants';
import { useCopyToClipboard } from '@/shared/hooks/clipboard/useCopyToClipboard';
import { PanelCloseButton, PanelHeaderMeta } from './PanelHeaderControls';
import type { CurrentSegmentImagesData } from '@/shared/components/VariantSelector/variantSourceImages';

const NOOP = () => {};

interface EditPanelLayoutProps {
  /** Layout variant */
  variant: 'desktop' | 'mobile';

  /** Handler to close the lightbox */
  onClose: () => void;

  /** Handler to exit edit mode (switch to info view) */
  onExitEditMode: () => void;

  /** Whether to hide the Info/Edit toggle */
  hideInfoEditToggle?: boolean;

  /**
   * Simplified header mode for page views (edit-images, edit-video tools).
   * When true, shows only [ModeSelector | X button] in header.
   * When false (default), shows full header with id copy, variants link, pending badge, etc.
   */
  simplifiedHeader?: boolean;

  /** Mode selector content (the toggle buttons) */
  modeSelector: React.ReactNode;

  /** Main content below the mode selector */
  children: React.ReactNode;

  /** Task ID for copy functionality */
  taskId?: string | null;

  /** Variants props */
  variants?: GenerationVariant[];
  activeVariantId?: string | null;
  onVariantSelect?: (variantId: string) => void;
  onMakePrimary?: (variantId: string) => Promise<void>;
  isLoadingVariants?: boolean;

  /** Variant promotion (only for images) */
  onPromoteToGeneration?: (variantId: string) => Promise<void>;
  isPromoting?: boolean;

  pendingTaskCount?: number;
  unviewedVariantCount?: number;
  onMarkAllViewed?: () => void;

  /** Handler to load a variant's settings into the regenerate form */
  onLoadVariantSettings?: (variantParams: Record<string, unknown>) => void;
  onLoadVariantImages?: (variant: GenerationVariant) => void;
  currentSegmentImages?: CurrentSegmentImagesData;

  /** Handler to delete a variant */
  onDeleteVariant?: (variantId: string) => Promise<void>;

}

export const EditPanelLayout: React.FC<EditPanelLayoutProps> = ({
  variant,
  onClose,
  onExitEditMode,
  hideInfoEditToggle = false,
  simplifiedHeader = false,
  modeSelector,
  children,
  taskId,
  variants,
  activeVariantId,
  onVariantSelect,
  onMakePrimary,
  isLoadingVariants,
  onPromoteToGeneration,
  isPromoting,
  pendingTaskCount = 0,
  unviewedVariantCount = 0,
  onMarkAllViewed = NOOP,
  onLoadVariantSettings,
  onLoadVariantImages,
  currentSegmentImages,
  onDeleteVariant,
}) => {
  const isMobile = variant === 'mobile';
  const hasVariants = variants && variants.length >= 1 && onVariantSelect;
  const padding = isMobile ? 'p-3' : 'p-6';
  const spacing = isMobile ? 'space-y-2' : 'space-y-4';
  const { copied: idCopied, handleCopy: handleCopyId } = useCopyToClipboard(taskId ?? undefined);
  const variantsSectionRef = useRef<HTMLDivElement>(null);

  return (
    <div className="h-full flex flex-col">
      {/* Header - simplified or full based on prop */}
      {simplifiedHeader ? (
        /* Simplified header for page views: just [ModeSelector | X] */
        <div className={cn(
          "flex items-center justify-between border-b border-border bg-background flex-shrink-0",
          isMobile ? "px-3 py-2 gap-2" : "p-4 gap-3"
        )}>
          {/* Mode selector takes available space */}
          <div className="flex-1">
            {modeSelector}
          </div>

          {/* Close button */}
          <PanelCloseButton
            isMobile={isMobile}
            onClose={onClose}
            stopPropagation
            className="flex-shrink-0"
          />
        </div>
      ) : (
        /* Full header for MediaLightbox: ID copy, variants link, pending badge, Info/Edit toggle, close */
        <div className={cn(
          "flex items-center justify-between border-b border-border bg-background flex-shrink-0",
          isMobile ? "px-3 py-2 gap-2" : "p-4 gap-3"
        )}>
          <PanelHeaderMeta
            taskId={taskId}
            idCopied={idCopied}
            onCopyId={handleCopyId}
            hasVariants={Boolean(hasVariants)}
            variants={variants ?? []}
            pendingTaskCount={pendingTaskCount}
            unviewedVariantCount={unviewedVariantCount}
            onMarkAllViewed={onMarkAllViewed}
            variantsSectionRef={variantsSectionRef}
          />

          {/* Right side - toggles and close button */}
          <div className="flex items-center gap-3">
            {!hideInfoEditToggle && (
              <SegmentedControl
                value="edit"
                onValueChange={(value) => {
                  if (value === 'info') {
                    onExitEditMode();
                  }
                }}
              >
                <SegmentedControlItem value="info">Info</SegmentedControlItem>
                <SegmentedControlItem value="edit">Edit</SegmentedControlItem>
              </SegmentedControl>
            )}
            <PanelCloseButton
              isMobile={isMobile}
              onClose={onClose}
              stopPropagation
            />
          </div>
        </div>
      )}

      {/* Scrollable content area */}
      <div className="flex-1 overflow-y-auto min-h-0 overscroll-none">
        {/* Mode selector section - only shown when NOT using simplified header */}
        {!simplifiedHeader && (
          <div className={cn("border-b border-border", isMobile ? "p-2" : "px-6 py-3")}>
            {modeSelector}
          </div>
        )}

        {/* Main content */}
        <div className={cn(padding, spacing)}>
          {children}
        </div>

        {/* Variants section - inside scroll area */}
        {hasVariants && (
          <div
            ref={variantsSectionRef}
            className={cn("border-t border-border", isMobile ? "pt-2 mt-2 px-3 pb-2" : "pt-4 mt-4 p-4")}
          >
            <VariantSelector
              variants={variants}
              activeVariantId={activeVariantId || null}
              onVariantSelect={onVariantSelect}
              onMakePrimary={onMakePrimary}
              isLoading={isLoadingVariants}
              onPromoteToGeneration={onPromoteToGeneration}
              isPromoting={isPromoting}
              onLoadVariantSettings={onLoadVariantSettings}
              onLoadVariantImages={onLoadVariantImages}
              currentSegmentImages={currentSegmentImages}
              onDeleteVariant={onDeleteVariant}
            />
          </div>
        )}
      </div>
    </div>
  );
};

  return (
    <div className="w-full h-full flex flex-col min-h-0">
      <div className="flex-1 min-h-0 overflow-y-auto">{sidebarContent}</div>
    </div>
  );
}

// ============================================================================
// InlineEditView — layout orchestrator (mobile vs desktop)
// ============================================================================

export function InlineEditView({ media, onClose, onNavigateToGeneration }: InlineEditViewProps) {
  const state = useInlineEditState(media, onNavigateToGeneration);
  const handleClose = useCallback(() => {
    void state.imageEditValue.flushTextFields();
    onClose();
  }, [state.imageEditValue, onClose]);
  const canvasModel = buildInlineEditCanvasModel(state);
  const sidebarModel = buildInlineEditSidebarModel(state);
  const isMobile = state.canvasEnvironment.isMobile;

  if (isMobile) {
    return (
      <TooltipProvider delayDuration={500}>
        <div className="w-full flex flex-col bg-transparent">
          <div
              className="flex items-center justify-center relative bg-black w-full shrink-0 rounded-t-2xl overflow-hidden"
              style={{ height: '45dvh', touchAction: 'pan-y' }}
            >
              <InlineEditCanvas variant="mobile" model={canvasModel} media={media} />
            </div>

            <div
              className={cn(
                "bg-background border-t border-border relative z-[60] w-full rounded-b-2xl pb-8"
              )}
              style={{ minHeight: '55dvh' }}
            >
              <InlineEditSidebar
                variant="mobile"
                model={sidebarModel}
                onClose={handleClose}
                onNavigateToGeneration={onNavigateToGeneration}
              />
            </div>
          </div>
        </TooltipProvider>
    );
  }

  return (
    <TooltipProvider delayDuration={500}>
      <div className="w-full h-full flex bg-transparent overflow-hidden">
        <div
            className="flex-1 flex items-center justify-center relative bg-black rounded-l-xl overflow-hidden"
            style={{ width: '60%', height: '100%' }}
          >
            <InlineEditCanvas variant="desktop" model={canvasModel} media={media} />
          </div>

          <div
            className={cn(
              "bg-background border-l border-border overflow-y-auto relative z-[60] rounded-r-xl"
            )}
            style={{ width: '40%', height: '100%' }}
          >
            <InlineEditSidebar
              variant="desktop"
              model={sidebarModel}
              onClose={handleClose}
              onNavigateToGeneration={onNavigateToGeneration}
            />
          </div>
        </div>
      </TooltipProvider>
  );
}

import React from 'react';
import type { GenerationRow } from '@/domains/generation/types';
import type {
  LightboxFeatureFlags,
} from '../types';
import { EditModePanel } from './EditModePanel';
import { InfoPanel } from './InfoPanel';
import { useLightboxCoreSafe, useLightboxVariantsSafe } from '../contexts/LightboxStateContext';
import type { ImageLightboxEnvironment } from '../hooks/useImageLightboxEnvironment';
import type { ImageLightboxEditModel } from '../hooks/useImageLightboxEditing';

interface ImageLightboxControlsPanelProps {
  media: GenerationRow;
  features?: LightboxFeatureFlags;
  env: ImageLightboxEnvironment;
  editModel: ImageLightboxEditModel;
  showPanel: boolean;
  panelVariant: 'desktop' | 'mobile';
  panelTaskId: string | null;
}

export const ImageLightboxControlsPanel = React.memo(function ImageLightboxControlsPanel({
  media,
  features,
  env,
  editModel,
  showPanel,
  panelVariant,
  panelTaskId,
}: ImageLightboxControlsPanelProps) {
  const coreState = useLightboxCoreSafe();
  const variantsState = useLightboxVariantsSafe();

  if (!showPanel) {
    return null;
  }

  const showImageEditTools = features?.showImageEditTools ?? true;
  const { editOrchestrator, adjustedTaskDetailsData } = editModel;

  if (editOrchestrator.isSpecialEditMode) {
    return (
      <EditModePanel
        variant={panelVariant}
        taskId={panelTaskId}
        currentMediaId={media.id}
        actions={{
          handleUnifiedGenerate: editOrchestrator.handleUnifiedGenerate,
          handleGenerateAnnotatedEdit: editOrchestrator.handleGenerateAnnotatedEdit,
          handleGenerateReposition: editOrchestrator.handleGenerateReposition,
          handleSaveAsVariant: editOrchestrator.handleSaveAsVariant,
          handleGenerateImg2Img: editOrchestrator.handleGenerateImg2Img,
        }}
        upscale={{
          isCloudMode: env.isCloudMode,
          handleUpscale: async () => {
            await env.upscaleHook.handleUpscale({ scaleFactor: 2, noiseScale: 0.1 });
          },
          isUpscaling: env.upscaleHook.isUpscaling,
          upscaleSuccess: env.upscaleHook.upscaleSuccess,
        }}
        lora={{
          img2imgLoraManager: editOrchestrator.img2imgLoraManager,
          editLoraManager: env.editLoraManager,
          availableLoras: env.availableLoras,
        }}
        advanced={{
          advancedSettings: env.editSettingsPersistence.advancedSettings,
          setAdvancedSettings: env.editSettingsPersistence.setAdvancedSettings,
        }}
        isLocalGeneration={env.isLocalGeneration}
        coreState={{ onClose: coreState.onClose }}
        imageEditState={editOrchestrator.imageEditValue}
        variantsState={variantsState}
      />
    );
  }

  return (
    <InfoPanel
      variant={panelVariant}
      showImageEditTools={showImageEditTools}
      taskPanel={{
        taskDetailsData: adjustedTaskDetailsData,
        replaceImages: env.replaceImages,
        onReplaceImagesChange: env.setReplaceImages,
      }}
      taskId={panelTaskId}
    />
  );
});

