describe('useInpainting', () => {
  beforeEach(() => {
    mockUseStrokePersistence.mockReset();
    mockUseTaskGeneration.mockReset();

    mockUseStrokePersistence.mockReturnValue({
      inpaintStrokes,
      annotationStrokes,
      brushSize: 24,
      setInpaintStrokes: vi.fn(),
      setAnnotationStrokes: vi.fn(),
      setBrushSize: vi.fn(),
    });

    mockUseTaskGeneration.mockReturnValue({
      handleGenerateInpaint: vi.fn(),
      handleGenerateAnnotatedEdit: vi.fn(),
    });
  });

  it('uses incoming edit settings props and forwards them to task generation', () => {
    const setEditMode = vi.fn();
    const setAnnotationMode = vi.fn();
    const setInpaintPrompt = vi.fn();
    const setInpaintNumGenerations = vi.fn();

    const { result } = renderHook(() =>
      useInpainting(createProps({
        shotId: 'shot-1',
        editMode: 'annotate',
        annotationMode: 'rectangle',
        inpaintPrompt: 'keep the skyline',
        inpaintNumGenerations: 3,
        setEditMode,
        setAnnotationMode,
        setInpaintPrompt,
        setInpaintNumGenerations,
      })),
    );

    expect(result.current.editMode).toBe('annotate');
    expect(result.current.annotationMode).toBe('rectangle');
    expect(result.current.inpaintPrompt).toBe('keep the skyline');
    expect(result.current.inpaintNumGenerations).toBe(3);
    expect(result.current.brushStrokes).toEqual(annotationStrokes);

    expect(mockUseTaskGeneration).toHaveBeenCalledWith(
      expect.objectContaining({
        inpaintStrokes,
        annotationStrokes,
        inpaintPrompt: 'keep the skyline',
        inpaintNumGenerations: 3,
      }),
    );
  });

  it('delegates edit-setting setters to incoming prop callbacks', () => {
    const setEditMode = vi.fn();
    const setAnnotationMode = vi.fn();
    const setInpaintPrompt = vi.fn();
    const setInpaintNumGenerations = vi.fn();

    const { result } = renderHook(() =>
      useInpainting(createProps({
        editMode: 'text',
        annotationMode: null,
        inpaintPrompt: '',
        inpaintNumGenerations: 1,
        setEditMode,
        setAnnotationMode,
        setInpaintPrompt,
        setInpaintNumGenerations,
      })),
    );

    act(() => {
      result.current.setEditMode('inpaint');
      result.current.setAnnotationMode('rectangle');
      result.current.setInpaintPrompt('new prompt');
      result.current.setInpaintNumGenerations(5);
    });

    expect(setEditMode).toHaveBeenCalledWith('inpaint');
    expect(setAnnotationMode).toHaveBeenCalledWith('rectangle');
    expect(setInpaintPrompt).toHaveBeenCalledWith('new prompt');
    expect(setInpaintNumGenerations).toHaveBeenCalledWith(5);
  });

  it('reflects caller-owned inpaint state across rerenders instead of keeping fallback copies', () => {
    const setAnnotationMode = vi.fn();
    const setInpaintPrompt = vi.fn();
    const setInpaintNumGenerations = vi.fn();

    const { result, rerender } = renderHook(
      (props: ReturnType<typeof createProps>) => useInpainting(props),
      {
        initialProps: createProps({
          media: { ...baseMedia, id: 'gen-1' },
          editMode: 'annotate',
          annotationMode: 'rectangle',
          inpaintPrompt: 'first prompt',
          inpaintNumGenerations: 2,
          setAnnotationMode,
          setInpaintPrompt,
          setInpaintNumGenerations,
        }),
      },
    );

    expect(result.current.annotationMode).toBe('rectangle');
    expect(result.current.inpaintPrompt).toBe('first prompt');
    expect(result.current.inpaintNumGenerations).toBe(2);

    rerender(createProps({
      media: { ...baseMedia, id: 'gen-2' },
      editMode: 'annotate',
      annotationMode: null,
      inpaintPrompt: 'second prompt',
      inpaintNumGenerations: 6,
      setAnnotationMode,
      setInpaintPrompt,
      setInpaintNumGenerations,
    }));

    expect(result.current.annotationMode).toBeNull();
    expect(result.current.inpaintPrompt).toBe('second prompt');
    expect(result.current.inpaintNumGenerations).toBe(6);
  });

  it.each(['reposition', 'img2img', 'upscale'] as const)(
    'passes through %s mode without exposing brush strokes',
    (editMode) => {
      const { result } = renderHook(() =>
        useInpainting(createProps({ editMode })),
      );

      expect(result.current.editMode).toBe(editMode);
      expect(result.current.brushStrokes).toEqual([]);
      expect(result.current.isAnnotateMode).toBe(false);
    },
  );
});

import type { GenerationRow } from '@/domains/generation/types';

// Import canonical types from single source of truth
import type { EditAdvancedSettings, EditMode, QwenEditModel } from '../../model/editSettingsTypes';

// StrokeOverlayHandle lives here to avoid a circular import
// (StrokeOverlay → shapeHelpers → types → StrokeOverlay).
export interface StrokeOverlayHandle {
  /** Renders all strokes as white-on-black mask at image resolution. */
  exportMask: (options?: { pixelRatio?: number }) => string | null;
  getSelectedShapeId: () => string | null;
  undo: () => void;
  clear: () => void;
  deleteSelected: () => void;
  toggleFreeForm: () => void;
}

// Re-export for backwards compatibility
export type { EditAdvancedSettings, EditMode, QwenEditModel };

// ============================================
// Core Types
// ============================================

export interface BrushStroke {
  id: string;
  points: Array<{ x: number; y: number }>; // 2 points for rectangle, 4 points for free-form quad
  isErasing: boolean;
  brushSize: number;
  shapeType?: 'line' | 'rectangle';
  isFreeForm?: boolean; // True if corners have been independently dragged
}

export type AnnotationMode = 'rectangle' | null;

interface ImageDimensions {
  width: number;
  height: number;
}

// ============================================
// Hook Props & Return Types
// ============================================

export interface UseInpaintingProps {
  media: GenerationRow;
  selectedProjectId: string | null;
  shotId?: string;
  toolTypeOverride?: string;
  isVideo: boolean;
  imageDimensions: ImageDimensions | null;
  imageContainerRef: React.RefObject<HTMLDivElement | null>;
  handleExitInpaintMode: () => void;
  loras?: Array<{ url: string; strength: number }>;
  activeVariantId?: string | null;
  activeVariantLocation?: string | null;
  createAsGeneration?: boolean;
  advancedSettings?: EditAdvancedSettings;
  qwenEditModel?: QwenEditModel;
  imageUrl?: string;
  thumbnailUrl?: string;
  editMode: EditMode;
  annotationMode: AnnotationMode;
  inpaintPrompt: string;
  inpaintNumGenerations: number;
  setEditMode: (mode: EditMode) => void;
  setAnnotationMode: (mode: AnnotationMode | ((prev: AnnotationMode) => AnnotationMode)) => void;
  setInpaintPrompt: (prompt: string) => void;
  setInpaintNumGenerations: (num: number) => void;
  /** Start with isInpaintMode=true (skips the "select an option" step) */
  initialActive?: boolean;
}

export interface UseInpaintingReturn {
  // State
  isInpaintMode: boolean;
  brushStrokes: BrushStroke[];
  isEraseMode: boolean;
  inpaintPrompt: string;
  inpaintNumGenerations: number;
  brushSize: number;
  isGeneratingInpaint: boolean;
  inpaintGenerateSuccess: boolean;
  isAnnotateMode: boolean;
  editMode: EditMode;
  annotationMode: AnnotationMode;
  selectedShapeId: string | null;
  showTextModeHint: boolean;

  // Setters
  setIsInpaintMode: React.Dispatch<React.SetStateAction<boolean>>;
  setInpaintPrompt: (prompt: string) => void;
  setInpaintNumGenerations: (num: number) => void;
  setBrushSize: (size: number) => void;
  setIsEraseMode: (isErasing: boolean) => void;
  setIsAnnotateMode: (isAnnotate: boolean | ((prev: boolean) => boolean)) => void;
  setEditMode: (mode: EditMode) => void;
  setAnnotationMode: (mode: AnnotationMode | ((prev: AnnotationMode) => AnnotationMode)) => void;

  // Handlers
  handleEnterInpaintMode: () => void;
  handleUndo: () => void;
  handleClearMask: () => void;
  handleGenerateInpaint: () => Promise<void>;
  handleGenerateAnnotatedEdit: () => Promise<void>;
  handleDeleteSelected: () => void;
  handleToggleFreeForm: () => void;
  getDeleteButtonPosition: () => { x: number; y: number } | null;

  // StrokeOverlay callbacks (passed as props to StrokeOverlay)
  onStrokeComplete: (stroke: BrushStroke) => void;
  onStrokesChange: (strokes: BrushStroke[]) => void;
  onSelectionChange: (shapeId: string | null) => void;
  onTextModeHint: () => void;

  // Refs
  strokeOverlayRef: React.RefObject<StrokeOverlayHandle>;

  // Canvas state
  isImageLoaded: boolean;
  imageLoadError: string | null;
}

export interface StrokeCache {
  inpaintStrokes: BrushStroke[];
  annotationStrokes: BrushStroke[];
  brushSize: number;
}

/**
 * useInpainting - Main hook for inpainting functionality
 *
 * This is the orchestrator that composes several sub-hooks:
 * - useStrokePersistence: Handles localStorage + in-memory stroke persistence
 * - useInpaintActions: Handles user actions (undo, clear, delete, etc.)
 * - useTaskGeneration: Handles task creation for inpaint/annotate edits
 *
 * StrokeOverlay owns the drawing state machine (pointer handlers, drag state).
 * This hook provides callbacks that StrokeOverlay invokes when strokes change.
 *
 * The sub-hooks are located in ./inpainting/
 */

