import { useReducer, useCallback, useRef, useMemo, useEffect } from 'react';
import { useToolSettings } from '@/shared/hooks/settings/useToolSettings';
import { useRenderLogger } from '@/shared/lib/debug/debugRendering';
import { useDebouncedSettingsSave } from '@/shared/settings/hooks/useDebouncedSettingsSave';
import { deepEqual } from '@/shared/lib/utils/deepEqual';
import { normalizeAndPresentError } from '@/shared/lib/errorHandling/runtimeError';
import { useCustomModeLoad, useReactQueryModeLoad } from '@/shared/settings/hooks/autoSaveSettingsLoaders';
import {
  applyEntityChangeState,
  applyLoadedDataState,
  transitionReadyWithPendingSave,
} from '@/shared/settings/hooks/autoSaveSettingsHelpers';

/**
 * Status states for the auto-save settings lifecycle.
 */
type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

interface AutoSaveState<T extends object> {
  entityId: string | null;
  settings: T;
  status: AutoSaveStatus;
  error: Error | null;
  hasPersistedData: boolean;
}

type AutoSaveAction<T extends object> =
  | {
      type: 'ENTITY_CHANGED';
      entityId: string | null;
      settings: T;
      status: AutoSaveStatus;
      error: Error | null;
      hasPersistedData: boolean;
    }
  | { type: 'LOAD_STARTED' }
  | { type: 'LOAD_RESOLVED'; settings: T; hasPersistedData: boolean }
  | {
      type: 'SETTINGS_UPDATED';
      nextSettings?: T;
      merge?: Partial<T>;
      status?: AutoSaveStatus;
      error?: Error | null;
      hasPersistedData?: boolean;
    };

function autoSaveSettingsReducer<T extends object>(
  state: AutoSaveState<T>,
  action: AutoSaveAction<T>
): AutoSaveState<T> {
  switch (action.type) {
    case 'ENTITY_CHANGED':
      return {
        entityId: action.entityId,
        settings: action.settings,
        status: action.status,
        error: action.error,
        hasPersistedData: action.hasPersistedData,
      };

    case 'LOAD_STARTED':
      return {
        ...state,
        status: 'loading',
        error: null,
      };

    case 'LOAD_RESOLVED':
      return {
        ...state,
        settings: action.settings,
        status: 'ready',
        error: null,
        hasPersistedData: action.hasPersistedData,
      };

    case 'SETTINGS_UPDATED': {
      const settings = action.nextSettings ?? { ...state.settings, ...action.merge };
      return {
        ...state,
        settings,
        status: action.status ?? state.status,
        error: Object.prototype.hasOwnProperty.call(action, 'error') ? (action.error ?? null) : state.error,
        hasPersistedData: Object.prototype.hasOwnProperty.call(action, 'hasPersistedData')
          ? (action.hasPersistedData ?? state.hasPersistedData)
          : state.hasPersistedData,
      };
    }

    default:
      return state;
  }
}

/**
 * Custom load/save functions for non-React-Query persistence.
 */
interface CustomLoadSave<T> {
  load: (entityId: string) => Promise<T | null>;
  save: (entityId: string, data: T) => Promise<void>;
  entityId: string | null;
  onFlush?: (entityId: string, data: T) => void;
}

interface UseAutoSaveSettingsOptions<T> {
  toolId?: string;
  shotId?: string | null;
  projectId?: string | null;
  scope?: 'shot' | 'project';
  debounceMs?: number;
  defaults: T;
  enabled?: boolean;
  debug?: boolean;
  debugTag?: string;
  onSaveSuccess?: () => void;
  onSaveError?: (error: Error) => void;
  customLoadSave?: CustomLoadSave<T>;
}

interface UseAutoSaveSettingsReturn<T> {
  settings: T;
  status: AutoSaveStatus;
  entityId: string | null;
  isDirty: boolean;
  error: Error | null;
  hasShotSettings: boolean;
  hasPersistedData: boolean;
  updateField: <K extends keyof T>(key: K, value: T[K]) => void;
  updateFields: (updates: Partial<T>) => void;
  updateTextField: <K extends keyof T>(key: K, value: T[K]) => void;
  updateTextFields: (updates: Partial<T>) => void;
  save: () => Promise<void>;
  saveImmediate: (dataToSave?: T) => Promise<void>;
  revert: () => void;
  reset: (newDefaults?: T) => void;
  initializeFrom: (data: Partial<T>) => void;
}

/**
 * Recommended hook for auto-saving settings to the database.
 *
 * This is the default choice for new features that need persisted settings.
 * Builds on `useToolSettings` (cascade resolution) and adds auto-save, dirty tracking,
 * entity-change handling, and unmount flushing.
 *
 * Features:
 * - Loads settings from DB with scope cascade (defaults -> user -> project -> shot)
 * - Debounced auto-save on field changes (default 300ms)
 * - Flushes pending saves on unmount/navigation
 * - Dirty tracking for unsaved changes indicator
 * - Status machine for loading states
 * - Optional customLoadSave mode for non-React-Query persistence
 *
 * CRITICAL: During loading (status !== 'ready'), updates only affect local UI state.
 * This prevents auto-initialization effects from blocking DB values.
 *
 * @see docs/structure_detail/settings_system.md for the full settings hook decision tree
 *
 * @example
 * ```typescript
 * // React Query mode (tool settings)
 * const settings = useAutoSaveSettings({
 *   toolId: 'my-tool',
 *   shotId: selectedShotId,
 *   scope: 'shot',
 *   defaults: { prompt: '', mode: 'basic' },
 * });
 *
 * // Custom load/save mode
 * const settings = useAutoSaveSettings({
 *   defaults: { prompt: '', mode: 'basic' },
 *   customLoadSave: {
 *     entityId: generationId,
 *     load: (id) => fetchFromDB(id),
 *     save: (id, data) => saveToDB(id, data),
 *   },
 * });
 *
 * // Update a field (auto-saves after debounce)
 * settings.updateField('prompt', 'new prompt');
 *
 * // Check if ready before rendering
 * if (settings.status !== 'ready') return <Loading />;
 * ```
 */
export function useAutoSaveSettings<T extends object>(
  options: UseAutoSaveSettingsOptions<T>
): UseAutoSaveSettingsReturn<T> {
  const {
    toolId = '',
    shotId,
    projectId,
    scope = 'shot',
    debounceMs = 300,
    defaults,
    enabled = true,
    onSaveSuccess,
    onSaveError,
    customLoadSave,
  } = options;

  const isCustomMode = !!customLoadSave;

  // Determine the entity ID based on mode
  const entityId = isCustomMode
    ? customLoadSave.entityId
    : (scope === 'shot' ? shotId : projectId) ?? null;
  const isEntityValid = !!entityId;

  // Reducer-backed state is the single source of truth for entity/status/settings transitions.
  const [state, dispatch] = useReducer(autoSaveSettingsReducer<T>, {
    entityId,
    settings: JSON.parse(JSON.stringify(defaults)),
    status: entityId ? 'idle' : 'idle',
    error: null,
    hasPersistedData: false,
  });

  // Refs for tracking state without triggering re-renders
  const loadedSettingsRef = useRef<T | null>(null);
  const isLoadingRef = useRef(false);
  const stateRef = useRef<AutoSaveState<T>>(state);

  // Stable refs for custom callbacks to avoid effect dependency churn
  const customLoadRef = useRef(customLoadSave?.load);
  const customSaveRef = useRef(customLoadSave?.save);
  const onFlushRef = useRef(customLoadSave?.onFlush);
  customLoadRef.current = customLoadSave?.load;
  customSaveRef.current = customLoadSave?.save;
  onFlushRef.current = customLoadSave?.onFlush;

  // Fetch settings from database (React Query mode only)
  const {
    settings: dbSettings,
    isLoading: rqIsLoading,
    update: updateSettings,
    hasShotSettings,
  } = useToolSettings<T>(toolId, {
    shotId: scope === 'shot' ? (shotId || undefined) : undefined,
    projectId: projectId || undefined,
    enabled: !isCustomMode && enabled && isEntityValid,
  });

  const entityChangeState = useMemo(() => applyEntityChangeState({
    entityId,
    previousEntityId: state.entityId,
    defaults,
    isCustomMode,
    rqIsLoading,
    dbSettings,
  }), [entityId, state.entityId, defaults, isCustomMode, rqIsLoading, dbSettings]);

  const viewState = useMemo(() => (
    entityChangeState
      ? {
          ...state,
          ...entityChangeState.nextState,
        }
      : state
  ), [entityChangeState, state]);

import { useRef, useEffect, useMemo, useState, useCallback } from 'react';
import { useGenerationEditSettings } from '../useGenerationEditSettings';
import { useLastUsedEditSettings } from '../useLastUsedEditSettings';

// Import canonical types from single source of truth
import {
  type EditMode,
  type LoraMode,
  type QwenEditModel,
  type EditAdvancedSettings,
  type VideoEnhanceSettings,
  type GenerationEditSettings,
  type EditSettingsSetterMethods,
  type LastUsedEditSettings,
  type VideoEditSubMode,
  type PanelMode,
  DEFAULT_EDIT_SETTINGS,
  DEFAULT_ADVANCED_SETTINGS,
  DEFAULT_ENHANCE_SETTINGS,
} from '../../model/editSettingsTypes';
import { resolveEditModeLoras } from '@/domains/lora/lib/loraUtils';

interface UseEditSettingsPersistenceProps {
  generationId: string | null;
  projectId: string | null;
  enabled?: boolean;
}

interface UseEditSettingsPersistenceReturn extends EditSettingsSetterMethods {
  // Current settings values
  editMode: EditMode;
  loraMode: LoraMode;
  customLoraUrl: string;
  numGenerations: number;
  prompt: string;
  // Img2Img values
  img2imgPrompt: string;
  img2imgPromptHasBeenSet: boolean;
  img2imgStrength: number;
  img2imgEnablePromptExpansion: boolean;
  // Advanced settings for two-pass generation
  advancedSettings: EditAdvancedSettings;
  // Video enhance settings (interpolation/upscaling)
  enhanceSettings: VideoEnhanceSettings;
  // Model selection for cloud mode
  qwenEditModel: QwenEditModel;
  // Generation options
  createAsGeneration: boolean;

  // Video/Panel mode settings (persisted to "last used" only)
  videoEditSubMode: VideoEditSubMode;
  panelMode: PanelMode;
  setVideoEditSubMode: (mode: VideoEditSubMode) => void;
  setPanelMode: (mode: PanelMode) => void;

  // Computed LoRAs for task creation
  editModeLoras: Array<{ url: string; strength: number }> | undefined;
  flushTextFields: () => Promise<void>;

  // State
  isLoading: boolean;
  isReady: boolean; // True when initialization is complete
  hasPersistedSettings: boolean;
}

/**
 * Unified edit settings persistence hook
 *
 * Coordinates:
 * 1. Per-generation settings (generations.params.ui.editSettings)
 * 2. "Last used" settings (useToolSettings + localStorage)
 *
 * Loading behavior:
 * - If generation has persisted settings → use those (including prompt)
 * - If no persisted settings → use "last used" (prompt = '')
 *
 * Saving behavior:
 * - All changes save to generation
 * - Non-prompt changes also update "last used"
 */
export function useEditSettingsPersistence({
  generationId,
  projectId,
  enabled = true,
}: UseEditSettingsPersistenceProps): UseEditSettingsPersistenceReturn {
  // Per-generation settings
  const generationSettings = useGenerationEditSettings({
    generationId,
    enabled,
  });

  // "Last used" settings
  const lastUsedSettings = useLastUsedEditSettings({
    projectId,
    enabled,
  });

  // Track initialization state
  const hasInitializedRef = useRef(false);
  const lastGenerationIdRef = useRef<string | null>(generationId);
  const [isReady, setIsReady] = useState(false);

  // Extract stable references
  const { isLoading: genIsLoading, hasPersistedSettings, initializeFromLastUsed } = generationSettings;
  const { lastUsed } = lastUsedSettings;

  // Reset the coordinator when the generation changes. `useAutoSaveSettings` now previews
  // the new entity state during render, so this can live in an effect without flashing stale values.
  useEffect(() => {
    if (generationId === lastGenerationIdRef.current) {
      return;
    }

    hasInitializedRef.current = false;
    lastGenerationIdRef.current = generationId;
    setIsReady(false);
  }, [generationId]);

  // Effect-based init: must be an effect (not render-time) because initializeFromLastUsed
  // calls setState on another hook (useGenerationEditSettings), which React forbids during
  // a parent's render phase.
  useEffect(() => {
    if (!genIsLoading && !hasInitializedRef.current) {
      if (!hasPersistedSettings && generationId) {
        hasInitializedRef.current = true;
        initializeFromLastUsed(lastUsed);
        setIsReady(true);
      } else if (hasPersistedSettings) {
        hasInitializedRef.current = true;
        setIsReady(true);
      }
    }
  }, [generationId, genIsLoading, hasPersistedSettings, initializeFromLastUsed, lastUsed]);

  // Compute effective values
  // editMode is ALWAYS from lastUsed (user-level, not per-generation) so it stays consistent across images/videos
  // Other settings like prompt, loraMode are per-generation
  const effectiveSettings = useMemo(() => {
    if (generationSettings.isLoading) {
      // Still loading, use defaults but editMode from lastUsed
      return {
        ...DEFAULT_EDIT_SETTINGS,
        editMode: lastUsedSettings.lastUsed.editMode,
      };
    }

    if (generationSettings.hasPersistedSettings) {
      // Has persisted settings, use them BUT override editMode with lastUsed (user-level)
      return {
        ...generationSettings.settings,
        editMode: lastUsedSettings.lastUsed.editMode,
      };
    }

    // No persisted settings yet.
    // Before the coordinator finishes initialization, we use lastUsed as defaults.
    // After initialization, always prefer the live generationSettings state so controls
    // (like the Img2Img strength slider) never feel "locked" while the debounced save runs.
    if (!isReady) {
      return {
        editMode: lastUsedSettings.lastUsed.editMode,
        loraMode: lastUsedSettings.lastUsed.loraMode,
        customLoraUrl: lastUsedSettings.lastUsed.customLoraUrl,
        numGenerations: lastUsedSettings.lastUsed.numGenerations,
        prompt: generationSettings.settings.prompt || '',
        img2imgPrompt: generationSettings.settings.img2imgPrompt || '',
        img2imgPromptHasBeenSet: generationSettings.settings.img2imgPromptHasBeenSet || false,
        img2imgStrength: lastUsedSettings.lastUsed.img2imgStrength,
        img2imgEnablePromptExpansion: lastUsedSettings.lastUsed.img2imgEnablePromptExpansion,
        advancedSettings: lastUsedSettings.lastUsed.advancedSettings ?? DEFAULT_ADVANCED_SETTINGS,
        enhanceSettings: generationSettings.settings.enhanceSettings ?? DEFAULT_ENHANCE_SETTINGS,
        qwenEditModel: generationSettings.settings.qwenEditModel ?? DEFAULT_EDIT_SETTINGS.qwenEditModel,
        createAsGeneration: lastUsedSettings.lastUsed.createAsGeneration,
      };
    }

    // Initialized: use the live per-generation state BUT override editMode with lastUsed (user-level)
    return {
      ...generationSettings.settings,
      editMode: lastUsedSettings.lastUsed.editMode,
    };
  }, [
    isReady,
    generationSettings.isLoading,
    generationSettings.hasPersistedSettings,
    generationSettings.settings,
    lastUsedSettings.lastUsed,
  ]);

  // Extract stable function references to avoid recreating callbacks on every render
  // (the parent objects are recreated each render, but these functions are stable)
  const { updateLastUsed } = lastUsedSettings;
  const {
    setEditMode: genSetEditMode,
    setLoraMode: genSetLoraMode,
    setCustomLoraUrl: genSetCustomLoraUrl,
    setNumGenerations: genSetNumGenerations,
    setPrompt: genSetPrompt,
    setQwenEditModel: genSetQwenEditModel,
    setImg2imgPrompt: genSetImg2imgPrompt,
    setImg2imgStrength: genSetImg2imgStrength,
    setImg2imgEnablePromptExpansion: genSetImg2imgEnablePromptExpansion,
    setAdvancedSettings: genSetAdvancedSettings,
    setEnhanceSettings: genSetEnhanceSettings,
    setCreateAsGeneration: genSetCreateAsGeneration,
    flushTextFields: flushGenerationTextFields,
  } = generationSettings;

  // Wrapper setters that also update "last used" (except prompt)
  // editMode writes to both generation persistence and user-level last used state.
  const setEditMode = useCallback((mode: EditMode) => {
    genSetEditMode(mode);
    updateLastUsed({ editMode: mode });
  }, [genSetEditMode, updateLastUsed]);

  const setLoraMode = useCallback((mode: LoraMode) => {
    genSetLoraMode(mode);
    updateLastUsed({ loraMode: mode });
  }, [genSetLoraMode, updateLastUsed]);

  const setCustomLoraUrl = useCallback((url: string) => {
    genSetCustomLoraUrl(url);
  }, [genSetCustomLoraUrl]);

  const setNumGenerations = useCallback((num: number) => {
    genSetNumGenerations(num);
    updateLastUsed({ numGenerations: num });
  }, [genSetNumGenerations, updateLastUsed]);

  // Prompt only saves to generation (never to "last used")
  const setPrompt = useCallback((prompt: string) => {
    genSetPrompt(prompt);
  }, [genSetPrompt]);

  // Model selection (saves to generation, cloud mode only)
  const setQwenEditModel = useCallback((model: QwenEditModel) => {
    genSetQwenEditModel(model);
  }, [genSetQwenEditModel]);

  // Img2Img prompt only saves to generation (never to "last used")
  const setImg2imgPrompt = useCallback((prompt: string) => {
    genSetImg2imgPrompt(prompt);
  }, [genSetImg2imgPrompt]);

  const flushTextFields = useCallback(async () => {
    await flushGenerationTextFields();
    updateLastUsed({ customLoraUrl: generationSettings.settings.customLoraUrl });
  }, [flushGenerationTextFields, updateLastUsed, generationSettings.settings.customLoraUrl]);

  // Img2Img setters (save to both generation and "last used")
