import { useEffect } from 'react';
import type { MutableRefObject } from 'react';
import { deepEqual } from '@/shared/lib/utils/deepEqual';
import { normalizeAndPresentError } from '@/shared/lib/errorHandling/runtimeError';
import { useDebouncedSettingsSave } from '@/shared/settings/hooks/useDebouncedSettingsSave';

type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

interface CustomModeLoadContext<T extends object> {
  isCustomMode: boolean;
  entityId: string | null;
  enabled: boolean;
  status: AutoSaveStatus;
  defaults: T;
  debouncedSave: ReturnType<typeof useDebouncedSettingsSave<T>>;
  customLoadRef: MutableRefObject<((entityId: string) => Promise<T | null>) | undefined>;
  stateRef: MutableRefObject<{ entityId: string | null; settings: T; hasPersistedData: boolean }>;
  isLoadingRef: MutableRefObject<boolean>;
  transitionReadyWithPendingSave: () => void;
  applyLoadedData: (data: T, hadPersistedData: boolean) => void;
  startLoad: () => void;
  setLoadError: (e: Error) => void;
}

interface ReactQueryModeLoadContext<T extends object> {
  isCustomMode: boolean;
  entityId: string | null;
  enabled: boolean;
  status: AutoSaveStatus;
  defaults: T;
  dbSettings: T | undefined;
  rqIsLoading: boolean;
  debouncedSave: ReturnType<typeof useDebouncedSettingsSave<T>>;
  loadedSettingsRef: MutableRefObject<T | null>;
  transitionReadyWithPendingSave: () => void;
  applyLoadedData: (data: T, hadPersistedData: boolean) => void;
  startLoad: () => void;
  markReady: () => void;
}

export function useCustomModeLoad<T extends object>(ctx: CustomModeLoadContext<T>) {
  const {
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    debouncedSave,
    customLoadRef,
    stateRef,
    isLoadingRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    setLoadError,
  } = ctx;

  useEffect(() => {
    if (!isCustomMode || !entityId || !enabled) {
      return;
    }
    if (status !== 'idle' && status !== 'loading') {
      return;
    }
    if (isLoadingRef.current) {
      return;
    }

    // Keep this guard: pending refs still protect typed-but-unflushed text edits from async loads.
    if (debouncedSave.hasPendingFor(entityId)) {
      transitionReadyWithPendingSave();
      return;
    }

    startLoad();
    isLoadingRef.current = true;

    customLoadRef.current!(entityId)
      .then((loaded) => {
        if (stateRef.current.entityId !== entityId) {
          return;
        }

        // Keep this guard: a load that resolves after local typing must not overwrite pending text state.
        if (debouncedSave.hasPendingFor(entityId)) {
          isLoadingRef.current = false;
          transitionReadyWithPendingSave();
          return;
        }

        isLoadingRef.current = false;
        applyLoadedData(loaded ? { ...defaults, ...loaded } : defaults, !!loaded);
      })
      .catch((err) => {
        normalizeAndPresentError(err, { context: 'useAutoSaveSettings.load', showToast: false });
        isLoadingRef.current = false;
        setLoadError(err as Error);
      });
  }, [
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    debouncedSave,
    customLoadRef,
    stateRef,
    isLoadingRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    setLoadError,
  ]);
}

export function useReactQueryModeLoad<T extends object>(ctx: ReactQueryModeLoadContext<T>) {
  const {
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    dbSettings,
    rqIsLoading,
    debouncedSave,
    loadedSettingsRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    markReady,
  } = ctx;

  useEffect(() => {
    if (isCustomMode || !entityId || !enabled) {
      return;
    }

    if (rqIsLoading) {
      if (status === 'idle') {
        startLoad();
      }
      return;
    }

    if (status === 'saving') {
      return;
    }

    // Keep this guard: React Query cache refreshes must not stomp pending text edits for the same entity.
    if (debouncedSave.hasPendingFor(entityId)) {
      if (status !== 'ready') {
        transitionReadyWithPendingSave();
      }
      return;
    }

    const loadedSettings: T = { ...defaults, ...(dbSettings || {}) };
    const clonedSettings = JSON.parse(JSON.stringify(loadedSettings));

    if (loadedSettingsRef.current && deepEqual(clonedSettings, loadedSettingsRef.current)) {
      if (status !== 'ready') {
        markReady();
      }
      return;
    }

    applyLoadedData(clonedSettings, !!dbSettings);
  }, [
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    dbSettings,
    rqIsLoading,
    debouncedSave,
    loadedSettingsRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    markReady,
  ]);
}

  ), [entityChangeState, state]);

  useEffect(() => {
    stateRef.current = viewState;
  }, [viewState]);

  useEffect(() => {
    if (!entityChangeState) {
      return;
    }

    loadedSettingsRef.current = entityChangeState.loadedSettings;
    isLoadingRef.current = false;
    dispatch({
      type: 'ENTITY_CHANGED',
      ...entityChangeState.nextState,
    });
  }, [entityChangeState]);

  useRenderLogger(`AutoSaveSettings:${toolId}`, { entityId: viewState.entityId, status: viewState.status });

  // Dirty flag - has user changed anything since load?
  const effectiveLoadedSettings = entityChangeState ? entityChangeState.loadedSettings : loadedSettingsRef.current;
  const isDirty = useMemo(
    () => (effectiveLoadedSettings ? !deepEqual(viewState.settings, effectiveLoadedSettings) : false),
    [viewState.settings, effectiveLoadedSettings]
  );

  // Save implementation
  const saveImmediate = useCallback(async (settingsToSave?: T): Promise<void> => {
    const currentEntityId = stateRef.current.entityId;
    if (!currentEntityId) {
      return;
    }

    const toSave = settingsToSave ?? stateRef.current.settings;

    // Don't save if nothing changed
    if (deepEqual(toSave, loadedSettingsRef.current)) {
      return;
    }

    stateRef.current = {
      ...stateRef.current,
      status: 'saving',
      error: null,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: toSave,
      status: 'saving',
      error: null,
    });

    try {
      if (isCustomMode) {
        await customSaveRef.current!(currentEntityId, toSave);
      } else {
        await updateSettings(scope, toSave);
      }

      // Update our "clean" reference
      loadedSettingsRef.current = JSON.parse(JSON.stringify(toSave));

      // NOTE: Don't clear pendingSettingsRef here - the scheduling layer only clears it
      // when the saved payload still matches the latest tracked local edits.

      const latestSettings = stateRef.current.settings;
      stateRef.current = {
        ...stateRef.current,
        settings: latestSettings,
        status: 'ready',
        error: null,
        hasPersistedData: isCustomMode ? true : stateRef.current.hasPersistedData,
      };
      dispatch({
        type: 'SETTINGS_UPDATED',
        nextSettings: latestSettings,
        status: 'ready',
        error: null,
        hasPersistedData: isCustomMode ? true : undefined,
      });

      onSaveSuccess?.();
    } catch (err) {
      normalizeAndPresentError(err, { context: 'useAutoSaveSettings.save', showToast: false });
      stateRef.current = {
        ...stateRef.current,
        status: 'error',
        error: err as Error,
      };
      dispatch({
        type: 'SETTINGS_UPDATED',
        status: 'error',
        error: err as Error,
      });
      onSaveError?.(err as Error);
      throw err;
    }
  }, [isCustomMode, updateSettings, scope, onSaveSuccess, onSaveError]);

  // Ref to hold latest saveImmediate to avoid effect dependency churn
  const saveImmediateRef = useRef(saveImmediate);
  saveImmediateRef.current = saveImmediate;

  const getLatestSettings = useCallback((): Promise<T> => {
    return Promise.resolve(stateRef.current.settings);
  }, []);

  // Debounced save sub-hook — manages scheduling, pending tracking, and flush effects
  const debouncedSave = useDebouncedSettingsSave<T>({
    entityId,
    debounceMs,
    status: viewState.status,
    isCustomMode,
    scope,
    toolId,
    projectId,
    customSaveRef,
    onFlushRef,
    saveImmediateRef,
    getLatestSettings,
  });

  const applyFieldUpdate = useCallback((updates: Partial<T>, shouldScheduleSave: boolean) => {
    const updated = { ...stateRef.current.settings, ...updates };
    stateRef.current = {
      ...stateRef.current,
      settings: updated,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: updated,
    });

    // Always track pending settings - this protects user input from being overwritten by DB load.
    debouncedSave.trackPendingUpdate(updated, stateRef.current.entityId);

    if (shouldScheduleSave) {
      // Schedule auto-save (no-ops during loading - just keeps pending tracking).
      debouncedSave.scheduleSave(stateRef.current.entityId);
    }
  }, [debouncedSave]);

  // Update single field without capturing entity-specific state in the callback closure.
  const updateField = useCallback(<K extends keyof T>(key: K, value: T[K]) => {
    applyFieldUpdate({ [key]: value } as Partial<T>, true);
  }, [applyFieldUpdate]);

  // Update multiple fields at once without capturing entity-specific state in the callback closure.
  const updateFields = useCallback((updates: Partial<T>) => {
    applyFieldUpdate(updates, true);
  }, [applyFieldUpdate]);

  // Free-text fields update local state immediately but wait for explicit blur/generate/close flushes.
  const updateTextField = useCallback(<K extends keyof T>(key: K, value: T[K]) => {
    applyFieldUpdate({ [key]: value } as Partial<T>, false);
  }, [applyFieldUpdate]);

  const updateTextFields = useCallback((updates: Partial<T>) => {
    applyFieldUpdate(updates, false);
  }, [applyFieldUpdate]);

  // Revert to last saved settings
  const revert = useCallback(() => {
    if (loadedSettingsRef.current) {
      stateRef.current = {
        ...stateRef.current,
        settings: loadedSettingsRef.current,
        error: null,
      };
      dispatch({
        type: 'SETTINGS_UPDATED',
        nextSettings: loadedSettingsRef.current,
        error: null,
      });
      debouncedSave.clearPending();
    }
  }, [debouncedSave]);

  // Manual save - flushes debounce immediately
  // Uses saveImmediateRef to avoid depending on saveImmediate directly
  const save = useCallback(async () => {
    debouncedSave.cancelPendingSave();
    await saveImmediateRef.current();
  }, [debouncedSave]);

  // Reset to defaults (or provided settings)
  const reset = useCallback((newDefaults?: T) => {
    const resetTo = JSON.parse(JSON.stringify(newDefaults || defaults)) as T;
    loadedSettingsRef.current = JSON.parse(JSON.stringify(resetTo));
    stateRef.current = {
      ...stateRef.current,
      settings: resetTo,
      error: null,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: resetTo,
      error: null,
    });
    debouncedSave.clearPending();
  }, [defaults, debouncedSave]);

  // Initialize from external source (e.g., "last used" settings) - custom mode only
  const initializeFrom = useCallback((data: Partial<T>) => {
    if (!isCustomMode) return;
    // Only apply if we don't have persisted data and aren't loading
    if (stateRef.current.hasPersistedData || isLoadingRef.current) {
      return;
    }

    const updated = { ...stateRef.current.settings, ...data };
    stateRef.current = {
      ...stateRef.current,
      settings: updated,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: updated,
    });
  }, [isCustomMode]);

  const transitionPendingLoadSave = useCallback(() => {
    transitionReadyWithPendingSave({
      markReady: () => {
        stateRef.current = {
          ...stateRef.current,
          status: 'ready',
          error: null,
        };
        dispatch({
          type: 'SETTINGS_UPDATED',
          nextSettings: stateRef.current.settings,
          status: 'ready',
          error: null,
        });
      },
      debouncedSave,
      saveImmediateRef,
      debounceMs,
    });
  }, [debouncedSave, saveImmediateRef, debounceMs]);

  const applyLoadedData = useCallback((data: T, hadPersistedData: boolean) => {
    const loadedState = applyLoadedDataState({
      data,
      hadPersistedData,
      isCustomMode,
    });
    loadedSettingsRef.current = loadedState.loadedSettings;
    isLoadingRef.current = false;
    stateRef.current = {
      ...stateRef.current,
      settings: loadedState.settings,
      status: loadedState.status,
      error: loadedState.error,
      hasPersistedData: loadedState.hasPersistedData,
    };
    dispatch({
      type: 'LOAD_RESOLVED',
      settings: loadedState.settings,
      hasPersistedData: loadedState.hasPersistedData,
    });
  }, [isCustomMode]);

  const startLoad = useCallback(() => {
    stateRef.current = {
      ...stateRef.current,
      status: 'loading',
      error: null,
    };
    dispatch({ type: 'LOAD_STARTED' });
  }, []);

  const setLoadError = useCallback((loadError: Error) => {
    stateRef.current = {
      ...stateRef.current,
      status: 'error',
      error: loadError,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      status: 'error',
      error: loadError,
    });
  }, []);

  const markReady = useCallback(() => {
    stateRef.current = {
      ...stateRef.current,
      status: 'ready',
      error: null,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: stateRef.current.settings,
      status: 'ready',
      error: null,
    });
  }, []);

  // Load settings - custom mode (imperative async load)
  useCustomModeLoad({
    isCustomMode,
    entityId,
    enabled,
    status: viewState.status,
    defaults,
    debouncedSave,
    customLoadRef,
    stateRef,
    isLoadingRef,
    transitionReadyWithPendingSave: transitionPendingLoadSave,
    applyLoadedData,
    startLoad,
    setLoadError,
  });

  // Load settings - React Query mode (reactive from useToolSettings)
  useReactQueryModeLoad({
    isCustomMode,
    entityId,
    enabled,
    status: viewState.status,
    defaults,
    dbSettings,
    rqIsLoading,
    debouncedSave,
    loadedSettingsRef,
    transitionReadyWithPendingSave: transitionPendingLoadSave,
    applyLoadedData,
    startLoad,
    markReady,
  });

  // Memoize return value to prevent object recreation on every render.
  return useMemo(() => ({
    settings: viewState.settings,
    status: viewState.status,
    entityId: viewState.entityId,
    isDirty,
    error: viewState.error,
    hasShotSettings: isCustomMode ? viewState.hasPersistedData : hasShotSettings,
    hasPersistedData: isCustomMode ? viewState.hasPersistedData : hasShotSettings,
    updateField,
    updateFields,
    updateTextField,
    updateTextFields,
    save,
    saveImmediate,
    revert,
    reset,
    initializeFrom,
  }), [viewState.settings, viewState.status, viewState.entityId, viewState.error, viewState.hasPersistedData, isDirty, isCustomMode, hasShotSettings, updateField, updateFields, updateTextField, updateTextFields, save, saveImmediate, revert, reset, initializeFrom]);
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import React from 'react';

// Mock dependencies
vi.mock('@/shared/hooks/settings/useToolSettings', () => ({
  useToolSettings: vi.fn().mockReturnValue({
    settings: null,
    isLoading: false,
    update: vi.fn().mockResolvedValue(undefined),
    hasShotSettings: false,
  }),
  updateToolSettingsSupabase: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('@/shared/lib/utils/deepEqual', () => ({
  deepEqual: (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b),
}));

vi.mock('@/shared/lib/errorHandling/runtimeError', () => ({
  normalizeAndPresentError: vi.fn(),
  reportRuntimeError: vi.fn(),
}));

import { useAutoSaveSettings } from '@/shared/settings/hooks/useAutoSaveSettings';
import { useToolSettings } from '@/shared/hooks/settings/useToolSettings';

type TestSettings = Record<string, unknown> & {
  prompt: string;
  mode: string;
};

function createWrapper() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  });
  return ({ children }: { children: React.ReactNode }) =>
    React.createElement(QueryClientProvider, { client: queryClient }, children);
}

describe('useAutoSaveSettings', () => {
  const defaults: TestSettings = { prompt: '', mode: 'basic' };

  beforeEach(() => {
    vi.useFakeTimers();
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe('initial state', () => {
    it('returns defaults as initial settings', () => {
      const { result } = renderHook(
        () => useAutoSaveSettings({ toolId: 'test', defaults, shotId: 'shot-1' }),
        { wrapper: createWrapper() }
      );

      expect(result.current.settings).toEqual(defaults);
    });

    it('starts with idle status when no entity', () => {
      const { result } = renderHook(
        () => useAutoSaveSettings({ toolId: 'test', defaults, shotId: null }),
        { wrapper: createWrapper() }
      );

      expect(result.current.status).toBe('idle');
