/**
 * Status states for the auto-save settings lifecycle.
 */
type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

interface AutoSaveState<T extends object> {
  entityId: string | null;
  settings: T;
  status: AutoSaveStatus;
  error: Error | null;
  hasPersistedData: boolean;
}

type AutoSaveAction<T extends object> =
  | {
      type: 'ENTITY_CHANGED';
      entityId: string | null;
      settings: T;
      status: AutoSaveStatus;
      error: Error | null;
      hasPersistedData: boolean;
    }
  | { type: 'LOAD_STARTED' }
  | { type: 'LOAD_RESOLVED'; settings: T; hasPersistedData: boolean }
  | {
      type: 'SETTINGS_UPDATED';
      nextSettings?: T;
      merge?: Partial<T>;
      status?: AutoSaveStatus;
      error?: Error | null;
      hasPersistedData?: boolean;
    };

function autoSaveSettingsReducer<T extends object>(
  state: AutoSaveState<T>,
  action: AutoSaveAction<T>
): AutoSaveState<T> {
  switch (action.type) {
    case 'ENTITY_CHANGED':
      return {
        entityId: action.entityId,
        settings: action.settings,
        status: action.status,
        error: action.error,
        hasPersistedData: action.hasPersistedData,
      };

    case 'LOAD_STARTED':
      return {
        ...state,
        status: 'loading',
        error: null,
      };

    case 'LOAD_RESOLVED':
      return {
        ...state,
        settings: action.settings,
        status: 'ready',
        error: null,
        hasPersistedData: action.hasPersistedData,
      };

    case 'SETTINGS_UPDATED': {
      const settings = action.nextSettings ?? { ...state.settings, ...action.merge };
      return {
        ...state,
        settings,
        status: action.status ?? state.status,
        error: Object.prototype.hasOwnProperty.call(action, 'error') ? (action.error ?? null) : state.error,
        hasPersistedData: Object.prototype.hasOwnProperty.call(action, 'hasPersistedData')
          ? (action.hasPersistedData ?? state.hasPersistedData)
          : state.hasPersistedData,
      };
    }

    default:
      return state;
  }
}

/**
 * Custom load/save functions for non-React-Query persistence.
 */
interface CustomLoadSave<T> {
  load: (entityId: string) => Promise<T | null>;
  save: (entityId: string, data: T) => Promise<void>;
  entityId: string | null;
  onFlush?: (entityId: string, data: T) => void;
}

interface UseAutoSaveSettingsOptions<T> {
  toolId?: string;
  shotId?: string | null;
  projectId?: string | null;
  scope?: 'shot' | 'project';
  debounceMs?: number;
  defaults: T;
  enabled?: boolean;
  debug?: boolean;
  debugTag?: string;
  onSaveSuccess?: () => void;
  onSaveError?: (error: Error) => void;
  customLoadSave?: CustomLoadSave<T>;
}

interface UseAutoSaveSettingsReturn<T> {
  settings: T;
  status: AutoSaveStatus;
  entityId: string | null;
  isDirty: boolean;
  error: Error | null;
  hasShotSettings: boolean;
  hasPersistedData: boolean;
  updateField: <K extends keyof T>(key: K, value: T[K]) => void;
  updateFields: (updates: Partial<T>) => void;
  updateTextField: <K extends keyof T>(key: K, value: T[K]) => void;
  updateTextFields: (updates: Partial<T>) => void;
  save: () => Promise<void>;
  saveImmediate: (dataToSave?: T) => Promise<void>;
  revert: () => void;
  reset: (newDefaults?: T) => void;
  initializeFrom: (data: Partial<T>) => void;
}

/**
 * Recommended hook for auto-saving settings to the database.
 *
 * This is the default choice for new features that need persisted settings.
 * Builds on `useToolSettings` (cascade resolution) and adds auto-save, dirty tracking,
 * entity-change handling, and unmount flushing.
 *
 * Features:
 * - Loads settings from DB with scope cascade (defaults -> user -> project -> shot)
 * - Debounced auto-save on field changes (default 300ms)
 * - Flushes pending saves on unmount/navigation
 * - Dirty tracking for unsaved changes indicator
 * - Status machine for loading states
 * - Optional customLoadSave mode for non-React-Query persistence
 *
 * CRITICAL: During loading (status !== 'ready'), updates only affect local UI state.
 * This prevents auto-initialization effects from blocking DB values.
 *
 * @see docs/structure_detail/settings_system.md for the full settings hook decision tree
 *
 * @example
 * ```typescript
 * // React Query mode (tool settings)
 * const settings = useAutoSaveSettings({
 *   toolId: 'my-tool',
 *   shotId: selectedShotId,
 *   scope: 'shot',
 *   defaults: { prompt: '', mode: 'basic' },
 * });
 *
 * // Custom load/save mode
 * const settings = useAutoSaveSettings({
 *   defaults: { prompt: '', mode: 'basic' },
 *   customLoadSave: {
 *     entityId: generationId,
 *     load: (id) => fetchFromDB(id),
 *     save: (id, data) => saveToDB(id, data),
 *   },
 * });
 *
 * // Update a field (auto-saves after debounce)
 * settings.updateField('prompt', 'new prompt');
 *
 * // Check if ready before rendering
 * if (settings.status !== 'ready') return <Loading />;
 * ```
 */
export function useAutoSaveSettings<T extends object>(
  options: UseAutoSaveSettingsOptions<T>
): UseAutoSaveSettingsReturn<T> {
  const {
    toolId = '',
    shotId,
    projectId,
    scope = 'shot',
    debounceMs = 300,
    defaults,
    enabled = true,
    onSaveSuccess,
    onSaveError,
    customLoadSave,
  } = options;

  const isCustomMode = !!customLoadSave;

  // Determine the entity ID based on mode
  const entityId = isCustomMode
    ? customLoadSave.entityId
    : (scope === 'shot' ? shotId : projectId) ?? null;
  const isEntityValid = !!entityId;

  // Reducer-backed state is the single source of truth for entity/status/settings transitions.
  const [state, dispatch] = useReducer(autoSaveSettingsReducer<T>, {
    entityId,
    settings: JSON.parse(JSON.stringify(defaults)),
    status: entityId ? 'idle' : 'idle',
    error: null,
    hasPersistedData: false,
  });

  // Refs for tracking state without triggering re-renders
  const loadedSettingsRef = useRef<T | null>(null);
  const isLoadingRef = useRef(false);
  const stateRef = useRef<AutoSaveState<T>>(state);

  // Stable refs for custom callbacks to avoid effect dependency churn
  const customLoadRef = useRef(customLoadSave?.load);
  const customSaveRef = useRef(customLoadSave?.save);
  const onFlushRef = useRef(customLoadSave?.onFlush);
  customLoadRef.current = customLoadSave?.load;
  customSaveRef.current = customLoadSave?.save;
  onFlushRef.current = customLoadSave?.onFlush;

  // Fetch settings from database (React Query mode only)
  const {
    settings: dbSettings,
    isLoading: rqIsLoading,
    update: updateSettings,
    hasShotSettings,
  } = useToolSettings<T>(toolId, {
    shotId: scope === 'shot' ? (shotId || undefined) : undefined,
    projectId: projectId || undefined,
    enabled: !isCustomMode && enabled && isEntityValid,
  });

  useLayoutEffect(() => {
    const entityChange = resolveEntityChange({
      entityId,
      previousEntityId: state.entityId,
      defaults,
      isCustomMode,
      rqIsLoading,
      dbSettings,
    });

    if (!entityChange) {
      return;
    }

    loadedSettingsRef.current = entityChange.loadedSettings;
    isLoadingRef.current = false;
    stateRef.current = {
      ...stateRef.current,
      ...entityChange.action,
    };
    dispatch({
      type: 'ENTITY_CHANGED',
      ...entityChange.action,
    });
  }, [entityId, state.entityId, defaults, isCustomMode, rqIsLoading, dbSettings]);

  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  useRenderLogger(`AutoSaveSettings:${toolId}`, { entityId: state.entityId, status: state.status });

  // Dirty flag - has user changed anything since load?
  const isDirty = useMemo(
    () => (loadedSettingsRef.current ? !deepEqual(state.settings, loadedSettingsRef.current) : false),
    [state.settings]
  );

  // Save implementation
  const saveImmediate = useCallback(async (settingsToSave?: T): Promise<void> => {
    const currentEntityId = stateRef.current.entityId;
    if (!currentEntityId) {
      return;
    }

    const toSave = settingsToSave ?? stateRef.current.settings;

    // Don't save if nothing changed
    if (deepEqual(toSave, loadedSettingsRef.current)) {
      return;
    }

    stateRef.current = {
      ...stateRef.current,
      status: 'saving',
      error: null,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: toSave,
      status: 'saving',
      error: null,
    });

    try {
      if (isCustomMode) {
        await customSaveRef.current!(currentEntityId, toSave);
      } else {
        await updateSettings(scope, toSave);
      }

      // Update our "clean" reference
      loadedSettingsRef.current = JSON.parse(JSON.stringify(toSave));

      // NOTE: Don't clear pendingSettingsRef here - the scheduling layer only clears it
      // when the saved payload still matches the latest tracked local edits.

import { useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { generationQueryKeys } from '@/shared/lib/queryKeys/generations';
import { useAutoSaveSettings } from '@/shared/settings/hooks/useAutoSaveSettings';
import type { Json } from '@/integrations/supabase/jsonTypes';
import { toJson } from '@/shared/lib/supabaseTypeHelpers';
import { fetchGenerationRecordById } from '@/integrations/supabase/repositories/generationRepository';
import { updateGenerationParams } from '@/integrations/supabase/repositories/generationMutationsRepository';

// Import canonical types from single source of truth
import {
  type EditMode,
  type LoraMode,
  type QwenEditModel,
  type EditAdvancedSettings,
  type VideoEnhanceSettings,
  type GenerationEditSettings,
  type EditSettingsSetterMethods,
  type SyncedEditSettings,
  DEFAULT_EDIT_SETTINGS
} from '../model/editSettingsTypes';

// Re-export types for backwards compatibility
export type { EditMode, QwenEditModel, EditAdvancedSettings, VideoEnhanceSettings };
// Defaults are internal-only - import from editSettingsTypes directly if needed

/**
 * Result type for convertToHiresFixApiParams - includes num_inference_steps for single-pass mode.
 */
interface EditApiParams {
  num_inference_steps?: number;
  hires_scale?: number;
  hires_steps?: number;
  hires_denoise?: number;
  lightning_lora_strength_phase_1?: number;
  lightning_lora_strength_phase_2?: number;
}

type JsonObject = { [key: string]: Json | undefined };
type AutoSaveGenerationEditSettings = GenerationEditSettings & Record<string, unknown>;

/**
 * Converts EditAdvancedSettings to API params for task creation.
 * Returns hires params if two-pass is enabled, or just num_inference_steps if disabled.
 */
export function convertToHiresFixApiParams(settings: EditAdvancedSettings | undefined): EditApiParams | undefined {
  if (!settings) {
    return undefined;
  }

  if (!settings.enabled) {
    // Two-pass disabled: just return num_inference_steps for single-pass generation
    return {
      num_inference_steps: settings.num_inference_steps,
    };
  }

  // Two-pass enabled: return hires params (base_steps is used as num_inference_steps for phase 1)
  return {
    num_inference_steps: settings.base_steps,
    hires_scale: settings.hires_scale,
    hires_steps: settings.hires_steps,
    hires_denoise: settings.hires_denoise,
    lightning_lora_strength_phase_1: settings.lightning_lora_strength_phase_1,
    lightning_lora_strength_phase_2: settings.lightning_lora_strength_phase_2,
  };
}

interface UseGenerationEditSettingsReturn extends EditSettingsSetterMethods {
  // Current settings
  settings: GenerationEditSettings;

  // Bulk update
  updateSettings: (updates: Partial<GenerationEditSettings>) => void;
  flushTextFields: () => Promise<void>;

  // State
  isLoading: boolean;
  hasPersistedSettings: boolean;

  // For initialization from "last used"
  initializeFromLastUsed: (lastUsed: SyncedEditSettings & { editMode: EditMode }) => void;
}

interface UseGenerationEditSettingsProps {
  generationId: string | null;
  enabled?: boolean;
}

/**
 * Load settings from generations.params.ui.editSettings
 */
async function loadGenerationSettings(generationId: string): Promise<AutoSaveGenerationEditSettings | null> {
  const generation = await fetchGenerationRecordById(generationId);
  if (!generation) {
    return null;
  }

  const savedSettings = (generation.params as Record<string, unknown> | null | undefined)?.ui as Record<string, unknown> | undefined;
  const editSettings = savedSettings?.editSettings as Partial<GenerationEditSettings> | undefined;

  if (editSettings) {
    return {
      ...DEFAULT_EDIT_SETTINGS,
      ...editSettings,
    };
  }

  return null;
}

/**
 * Save settings to generations.params.ui.editSettings
 */
async function saveGenerationSettings(generationId: string, settings: AutoSaveGenerationEditSettings): Promise<void> {
  // Fetch current params to merge
  const current = await fetchGenerationRecordById(generationId);

  if (!current) {
    // Generation was deleted, skip save
    return;
  }

  // Merge with existing params
  const currentParams = ((current?.params as JsonObject | null) ?? {});
  const currentUi = ((currentParams.ui as JsonObject | undefined) ?? {});
  const updatedParams: JsonObject = {
    ...currentParams,
    ui: {
      ...currentUi,
      editSettings: toJson(settings),
      // Also save editMode at top level for backwards compatibility
      editMode: settings.editMode,
    }
  };

  await updateGenerationParams({
    id: generationId,
    generationParams: toJson(updatedParams),
  });
}

/**
 * Hook for managing per-generation edit settings persistence
 *
 * Uses useAutoSaveSettings (customLoadSave mode) for the core persistence logic:
 * - Status machine (idle → loading → ready → saving)
 * - Debounced auto-save
 * - Pending refs protection
 * - Flush on unmount/entity change
 *
 * Saves to: generations.params.ui.editSettings
 */
export function useGenerationEditSettings({
  generationId,
  enabled = true,
}: UseGenerationEditSettingsProps): UseGenerationEditSettingsReturn {
  const queryClient = useQueryClient();

  // Use the base persistent state hook (customLoadSave mode)
  const {
    settings,
    status,
    hasPersistedData: hasPersistedSettings,
    updateField,
    updateFields,
    updateTextField,
    updateTextFields,
    save,
    initializeFrom,
  } = useAutoSaveSettings<AutoSaveGenerationEditSettings>({
    defaults: DEFAULT_EDIT_SETTINGS as AutoSaveGenerationEditSettings,
    debounceMs: 500,
    enabled,
    debugTag: '[useGenerationEditSettings]',
    customLoadSave: {
      entityId: generationId,
      load: loadGenerationSettings,
      save: saveGenerationSettings,
      onFlush: (entityId) => {
        // Invalidate generation queries after flush
        queryClient.invalidateQueries({
          queryKey: generationQueryKeys.detail(entityId)
        });
      },
    },
    onSaveSuccess: () => {
      if (generationId) {
        queryClient.invalidateQueries({
          queryKey: generationQueryKeys.detail(generationId)
        });
      }
    },
  });

  // Individual setters that delegate to updateField
  const setEditMode = useCallback((mode: EditMode) => {
    updateField('editMode', mode);
  }, [updateField]);

  const setLoraMode = useCallback((mode: LoraMode) => {
    updateField('loraMode', mode);
  }, [updateField]);

  const setCustomLoraUrl = useCallback((url: string) => {
    updateTextField('customLoraUrl', url);
  }, [updateTextField]);

  const setNumGenerations = useCallback((num: number) => {
    updateField('numGenerations', num);
  }, [updateField]);

  const setPrompt = useCallback((prompt: string) => {
    updateTextField('prompt', prompt);
  }, [updateTextField]);

  const setQwenEditModel = useCallback((model: QwenEditModel) => {
    updateField('qwenEditModel', model);
  }, [updateField]);

  const setImg2imgPrompt = useCallback((prompt: string) => {
    updateTextFields({ img2imgPrompt: prompt, img2imgPromptHasBeenSet: true });
  }, [updateTextFields]);

  const setImg2imgStrength = useCallback((strength: number) => {
    updateField('img2imgStrength', strength);
  }, [updateField]);

  const setImg2imgEnablePromptExpansion = useCallback((enabled: boolean) => {
    updateField('img2imgEnablePromptExpansion', enabled);
  }, [updateField]);

  // Advanced settings setter (merges with existing)
  const setAdvancedSettings = useCallback((updates: Partial<EditAdvancedSettings>) => {
    updateFields({
      advancedSettings: { ...settings.advancedSettings, ...updates },
    });
  }, [updateFields, settings.advancedSettings]);

  // Video enhance settings setter (merges with existing)
  const setEnhanceSettings = useCallback((updates: Partial<VideoEnhanceSettings>) => {
    updateFields({
      enhanceSettings: { ...settings.enhanceSettings, ...updates },
    });
  }, [updateFields, settings.enhanceSettings]);

  const setCreateAsGeneration = useCallback((value: boolean) => {
    updateField('createAsGeneration', value);
  }, [updateField]);

  // Bulk update
  const updateSettings = useCallback((updates: Partial<GenerationEditSettings>) => {
    updateFields(updates);
  }, [updateFields]);

  const flushTextFields = useCallback(async () => {
    await save();
  }, [save]);

  // Initialize from "last used" - wraps initializeFrom with prompt exclusion
  const initializeFromLastUsed = useCallback((lastUsed: SyncedEditSettings & { editMode: EditMode }) => {
    // Apply last used but never inherit prompts
    initializeFrom({
      ...lastUsed,
      prompt: '',
      img2imgPrompt: '',
      img2imgPromptHasBeenSet: false,
    });
  }, [initializeFrom]);

  return {
    settings,
    setEditMode,
    setLoraMode,
    setCustomLoraUrl,
    setNumGenerations,
    setPrompt,
    setQwenEditModel,
    setImg2imgPrompt,
    setImg2imgStrength,
    setImg2imgEnablePromptExpansion,
    setAdvancedSettings,
    setEnhanceSettings,
    setCreateAsGeneration,
    updateSettings,
    flushTextFields,
    isLoading: status === 'loading' || status === 'idle',
    hasPersistedSettings,
    initializeFromLastUsed,
  };
}

