  debounceMs,
  status: state.status,
  isCustomMode,
  scope,
  toolId,
  projectId,
  customSaveRef,
  onFlushRef,
  saveImmediateRef,
  getLatestSettings,
});

const applyFieldUpdate = useCallback((updates: Partial<T>, shouldScheduleSave: boolean) => {
  const updated = { ...stateRef.current.settings, ...updates };
  stateRef.current = {
    ...stateRef.current,
    settings: updated,
  };
  dispatch({
    type: 'SETTINGS_UPDATED',
    nextSettings: updated,
  });

  // Always track pending settings - this protects user input from being overwritten by DB load.
  debouncedSave.trackPendingUpdate(updated, stateRef.current.entityId);

  if (shouldScheduleSave) {
    // Schedule auto-save (no-ops during loading - just keeps pending tracking).
    debouncedSave.scheduleSave(stateRef.current.entityId);
  }
}, [debouncedSave]);

// Update single field without capturing entity-specific state in the callback closure.
const updateField = useCallback(<K extends keyof T>(key: K, value: T[K]) => {
  applyFieldUpdate({ [key]: value } as Partial<T>, true);
}, [applyFieldUpdate]);

// Update multiple fields at once without capturing entity-specific state in the callback closure.
const updateFields = useCallback((updates: Partial<T>) => {
  applyFieldUpdate(updates, true);
}, [applyFieldUpdate]);

// Free-text fields update local state immediately but wait for explicit blur/generate/close flushes.
const updateTextField = useCallback(<K extends keyof T>(key: K, value: T[K]) => {
  applyFieldUpdate({ [key]: value } as Partial<T>, false);
}, [applyFieldUpdate]);

const updateTextFields = useCallback((updates: Partial<T>) => {
  applyFieldUpdate(updates, false);
}, [applyFieldUpdate]);

// Revert to last saved settings
const revert = useCallback(() => {
  if (loadedSettingsRef.current) {
    stateRef.current = {
      ...stateRef.current,
      settings: loadedSettingsRef.current,
      error: null,
    };
    dispatch({
      type: 'SETTINGS_UPDATED',
      nextSettings: loadedSettingsRef.current,
      error: null,
    });
    debouncedSave.clearPending();
  }
}, [debouncedSave]);

// Manual save - flushes debounce immediately
// Uses saveImmediateRef to avoid depending on saveImmediate directly
const save = useCallback(async () => {
  debouncedSave.cancelPendingSave();
  await saveImmediateRef.current();
}, [debouncedSave]);

// Reset to defaults (or provided settings)
const reset = useCallback((newDefaults?: T) => {
  const resetTo = JSON.parse(JSON.stringify(newDefaults || defaults)) as T;
  loadedSettingsRef.current = JSON.parse(JSON.stringify(resetTo));
  stateRef.current = {
    ...stateRef.current,
    settings: resetTo,
    error: null,
  };
  dispatch({
    type: 'SETTINGS_UPDATED',
    nextSettings: resetTo,
    error: null,
  });
  debouncedSave.clearPending();
}, [defaults, debouncedSave]);

// Initialize from external source (e.g., "last used" settings) - custom mode only
const initializeFrom = useCallback((data: Partial<T>) => {
  if (!isCustomMode) return;
  // Only apply if we don't have persisted data and aren't loading
  if (stateRef.current.hasPersistedData || isLoadingRef.current) {
    return;
  }

  const updated = { ...stateRef.current.settings, ...data };
  stateRef.current = {
    ...stateRef.current,
    settings: updated,
  };
  dispatch({
    type: 'SETTINGS_UPDATED',
    nextSettings: updated,
  });
}, [isCustomMode]);

const transitionPendingLoadSave = useCallback(() => {
  transitionReadyWithPendingSave({
    markReady: () => {
      stateRef.current = {
        ...stateRef.current,
        status: 'ready',
        error: null,
      };
      dispatch({
        type: 'SETTINGS_UPDATED',
        nextSettings: stateRef.current.settings,
        status: 'ready',
        error: null,
      });
    },
    debouncedSave,
    saveImmediateRef,
    debounceMs,
  });
}, [debouncedSave, saveImmediateRef, debounceMs]);

const applyLoadedData = useCallback((data: T, hadPersistedData: boolean) => {
  const loadedState = applyLoadedDataState({
    data,
    hadPersistedData,
    isCustomMode,
  });
  loadedSettingsRef.current = loadedState.loadedSettings;
  isLoadingRef.current = false;
  stateRef.current = {
    ...stateRef.current,
    settings: loadedState.settings,
    status: loadedState.status,
    error: loadedState.error,
    hasPersistedData: loadedState.hasPersistedData,
  };
  dispatch({
    type: 'LOAD_RESOLVED',
    settings: loadedState.settings,
    hasPersistedData: loadedState.hasPersistedData,
  });
}, [isCustomMode]);

const startLoad = useCallback(() => {

import { useDebouncedSettingsSave } from '@/shared/settings/hooks/useDebouncedSettingsSave';
import type { MutableRefObject } from 'react';

type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

function cloneSettings<T>(data: T): T {
  return JSON.parse(JSON.stringify(data));
}

interface TransitionReadyWithPendingSaveInput<T extends object> {
  markReady: () => void;
  debouncedSave: ReturnType<typeof useDebouncedSettingsSave<T>>;
  saveImmediateRef: MutableRefObject<(settingsToSave?: T) => Promise<void>>;
  debounceMs: number;
}

export function transitionReadyWithPendingSave<T extends object>({
  markReady,
  debouncedSave,
  saveImmediateRef,
  debounceMs,
}: TransitionReadyWithPendingSaveInput<T>): void {
  markReady();
  debouncedSave.cancelPendingSave();
  const toSave = debouncedSave.pendingSettingsRef.current!;
  debouncedSave.saveTimeoutRef.current = setTimeout(async () => {
    try {
      await saveImmediateRef.current(toSave);
    } catch {
      // surface handled at save layer; keep transition helper side-effect only
    }
  }, debounceMs);
}

interface ApplyLoadedDataInput<T extends object> {
  data: T;
  hadPersistedData: boolean;
  isCustomMode: boolean;
}

interface ApplyLoadedDataStateResult<T extends object> {
  settings: T;
  loadedSettings: T;
  hasPersistedData: boolean;
  status: AutoSaveStatus;
  error: Error | null;
}

export function applyLoadedDataState<T extends object>({
  data,
  hadPersistedData,
  isCustomMode,
}: ApplyLoadedDataInput<T>): ApplyLoadedDataStateResult<T> {
  const cloned = cloneSettings(data);
  return {
    settings: cloned,
    loadedSettings: cloneSettings(cloned),
    hasPersistedData: isCustomMode ? hadPersistedData : false,
    status: 'ready',
    error: null,
  };
}

interface ApplyEntityChangeStateInput<T extends object> {
  entityId: string | null;
  previousEntityId: string | null;
  defaults: T;
  isCustomMode: boolean;
  rqIsLoading: boolean;
  dbSettings: T | undefined;
}

interface ApplyEntityChangeStateResult<T extends object> {
  action: {
    entityId: string | null;
    settings: T;
    status: AutoSaveStatus;
    hasPersistedData: boolean;
    error: Error | null;
  };
  loadedSettings: T | null;
}

export function resolveEntityChange<T extends object>({
  entityId,
  previousEntityId,
  defaults,
  isCustomMode,
  rqIsLoading,
  dbSettings,
}: ApplyEntityChangeStateInput<T>): ApplyEntityChangeStateResult<T> | null {
  if (entityId === previousEntityId) {
    return null;
  }

  if (!entityId) {
    return {
      action: {
        entityId: null,
        settings: cloneSettings(defaults),
        status: 'idle',
        hasPersistedData: false,
        error: null,
      },
      loadedSettings: null,
    };
  }

  if (!isCustomMode && !rqIsLoading) {
    const loaded = cloneSettings({ ...defaults, ...(dbSettings as Record<string, unknown> | undefined) } as T);
    return {
      action: {
        entityId,
        settings: loaded,
        status: 'ready',
        hasPersistedData: false,
        error: null,
      },
      loadedSettings: cloneSettings(loaded),
    };
  }

  return {
    action: {
      entityId,
      settings: cloneSettings(defaults),
      status: 'loading',
      hasPersistedData: false,
      error: null,
    },
    loadedSettings: null,
  };
}

import { useEffect } from 'react';
import type { MutableRefObject } from 'react';
import { deepEqual } from '@/shared/lib/utils/deepEqual';
import { normalizeAndPresentError } from '@/shared/lib/errorHandling/runtimeError';
import { useDebouncedSettingsSave } from '@/shared/settings/hooks/useDebouncedSettingsSave';

type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

interface CustomModeLoadContext<T extends object> {
  isCustomMode: boolean;
  entityId: string | null;
  enabled: boolean;
  status: AutoSaveStatus;
  defaults: T;
  debouncedSave: ReturnType<typeof useDebouncedSettingsSave<T>>;
  customLoadRef: MutableRefObject<((entityId: string) => Promise<T | null>) | undefined>;
  stateRef: MutableRefObject<{ entityId: string | null; settings: T; hasPersistedData: boolean }>;
  isLoadingRef: MutableRefObject<boolean>;
  transitionReadyWithPendingSave: () => void;
  applyLoadedData: (data: T, hadPersistedData: boolean) => void;
  startLoad: () => void;
  setLoadError: (e: Error) => void;
}

interface ReactQueryModeLoadContext<T extends object> {
  isCustomMode: boolean;
  entityId: string | null;
  enabled: boolean;
  status: AutoSaveStatus;
  defaults: T;
  dbSettings: T | undefined;
  rqIsLoading: boolean;
  debouncedSave: ReturnType<typeof useDebouncedSettingsSave<T>>;
  loadedSettingsRef: MutableRefObject<T | null>;
  transitionReadyWithPendingSave: () => void;
  applyLoadedData: (data: T, hadPersistedData: boolean) => void;
  startLoad: () => void;
  markReady: () => void;
}

export function useCustomModeLoad<T extends object>(ctx: CustomModeLoadContext<T>) {
  const {
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    debouncedSave,
    customLoadRef,
    stateRef,
    isLoadingRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    setLoadError,
  } = ctx;

  useEffect(() => {
    if (!isCustomMode || !entityId || !enabled) {
      return;
    }
    if (status !== 'idle' && status !== 'loading') {
      return;
    }
    if (isLoadingRef.current) {
      return;
    }

    // Keep this guard: pending refs still protect typed-but-unflushed text edits from async loads.
    if (debouncedSave.hasPendingFor(entityId)) {
      transitionReadyWithPendingSave();
      return;
    }

    startLoad();
    isLoadingRef.current = true;

    customLoadRef.current!(entityId)
      .then((loaded) => {
        if (stateRef.current.entityId !== entityId) {
          return;
        }

        // Keep this guard: a load that resolves after local typing must not overwrite pending text state.
        if (debouncedSave.hasPendingFor(entityId)) {
          isLoadingRef.current = false;
          transitionReadyWithPendingSave();
          return;
        }

        isLoadingRef.current = false;
        applyLoadedData(loaded ? { ...defaults, ...loaded } : defaults, !!loaded);
      })
      .catch((err) => {
        normalizeAndPresentError(err, { context: 'useAutoSaveSettings.load', showToast: false });
        isLoadingRef.current = false;
        setLoadError(err as Error);
      });
  }, [
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    debouncedSave,
    customLoadRef,
    stateRef,
    isLoadingRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    setLoadError,
  ]);
}

export function useReactQueryModeLoad<T extends object>(ctx: ReactQueryModeLoadContext<T>) {
  const {
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    dbSettings,
    rqIsLoading,
    debouncedSave,
    loadedSettingsRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    markReady,
  } = ctx;

  useEffect(() => {
    if (isCustomMode || !entityId || !enabled) {
      return;
    }

    if (rqIsLoading) {
      if (status === 'idle') {
        startLoad();
      }
      return;
    }

    if (status === 'saving') {
      return;
    }

    // Keep this guard: React Query cache refreshes must not stomp pending text edits for the same entity.
    if (debouncedSave.hasPendingFor(entityId)) {
      if (status !== 'ready') {
        transitionReadyWithPendingSave();
      }
      return;
    }

    const loadedSettings: T = { ...defaults, ...(dbSettings || {}) };
    const clonedSettings = JSON.parse(JSON.stringify(loadedSettings));

    if (loadedSettingsRef.current && deepEqual(clonedSettings, loadedSettingsRef.current)) {
      if (status !== 'ready') {
        markReady();
      }
      return;
    }

    applyLoadedData(clonedSettings, !!dbSettings);
  }, [
    isCustomMode,
    entityId,
    enabled,
    status,
    defaults,
    dbSettings,
    rqIsLoading,
    debouncedSave,
    loadedSettingsRef,
    transitionReadyWithPendingSave,
    applyLoadedData,
    startLoad,
    markReady,
  ]);
}

import { useCallback, useEffect, useMemo, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useRenderLogger } from '@/shared/lib/debug/debugRendering';
import { updateToolSettingsSupabase } from '@/shared/hooks/settings/useToolSettings';
import { queryKeys } from '@/shared/lib/queryKeys';
import { normalizeAndPresentError } from '@/shared/lib/errorHandling/runtimeError';
import { deepEqual } from '@/shared/lib/utils/deepEqual';

type AutoSaveStatus = 'idle' | 'loading' | 'ready' | 'saving' | 'error';

interface UseDebouncedSettingsSaveOptions<T> {
  /** Current entity ID */
  entityId: string | null;
  /** Debounce delay in ms */
  debounceMs: number;
  /** Current hook status - saves are only scheduled when 'ready' or 'saving' */
  status: AutoSaveStatus;
  /** Whether using custom load/save mode (vs React Query mode) */
  isCustomMode: boolean;
  /** Settings scope for React Query mode flush */
  scope: 'shot' | 'project';
  /** Tool identifier for React Query mode flush */
  toolId: string;
  /** Project ID for React Query cache invalidation */
  projectId?: string | null;
  /** Ref to the custom save function (only used in custom mode) */
  customSaveRef: React.MutableRefObject<((entityId: string, data: T) => Promise<void>) | undefined>;
  /** Ref to optional onFlush callback (only used in custom mode) */
  onFlushRef: React.MutableRefObject<((entityId: string, data: T) => void) | undefined>;
  /** Ref to the latest saveImmediate function */
  saveImmediateRef: React.MutableRefObject<(settings: T) => Promise<void>>;
  /** Function to read the latest settings from state (via setSettings identity trick) */
  getLatestSettings: () => Promise<T>;
}

interface UseDebouncedSettingsSaveReturn<T> {
  /** Schedule a debounced save. Call this after updating settings state. */
  scheduleSave: (entityId: string | null) => void;
  /** Cancel any pending debounce timeout without saving. */
  cancelPendingSave: () => void;
  /**
   * Clear pending refs and cancel timeout. Used by revert/reset.
   * Does NOT trigger a save.
   */
  clearPending: () => void;
  /**
   * Record that settings were updated (tracks pending state for flush).
   * Call this BEFORE scheduleSave if the update should be flushed on unmount.
   */
  trackPendingUpdate: (settings: T, entityId: string | null) => void;
  /**
   * Check if there are pending edits for a given entity.
   * Used by load effects to avoid overwriting user input.
   */
  hasPendingFor: (entityId: string) => boolean;
  /** The pending settings ref (read-only access for load effects) */
  pendingSettingsRef: React.MutableRefObject<T | null>;
  /** The pending entity ID ref (read-only access for load effects) */
  pendingEntityIdRef: React.MutableRefObject<string | null>;
  /** The save timeout ref */
  saveTimeoutRef: React.MutableRefObject<NodeJS.Timeout | null>;
}

/**
 * Sub-hook that manages debounced save scheduling,
 * pending state tracking, and flush-on-unmount/entity-change/beforeunload.
 *
 * Extracted from useAutoSaveSettings to eliminate duplication between
 * updateField and updateFields, and to isolate the flush lifecycle.
 *
 * @internal Used only by useAutoSaveSettings
 */
export function useDebouncedSettingsSave<T extends object>(
  options: UseDebouncedSettingsSaveOptions<T>
): UseDebouncedSettingsSaveReturn<T> {
  const {
    entityId,
    debounceMs,
    status,
    isCustomMode,
    scope,
    toolId,
    projectId,
    customSaveRef,
    onFlushRef,
    saveImmediateRef,
    getLatestSettings,
  } = options;

  const queryClient = useQueryClient();

  useRenderLogger(`DebouncedSettingsSave:${toolId}`, { entityId, status });

  // Refs owned by this hook
  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const pendingSettingsRef = useRef<T | null>(null);
  const pendingEntityIdRef = useRef<string | null>(null);

  // Ref for status so scheduleSave can read it at call time without depending on it.
  // This is critical for reference stability: without it, scheduleSave changes on every
  // status transition (ready→saving→ready), cascading through the entire settings tree.
  const statusRef = useRef(status);
  statusRef.current = status;

  // Track pending update (called before scheduleSave)
  const trackPendingUpdate = useCallback((settings: T, forEntityId: string | null) => {
    pendingSettingsRef.current = settings;
    pendingEntityIdRef.current = forEntityId;
  }, []);

  // Check if there are pending edits for a given entity
  const hasPendingFor = useCallback((forEntityId: string): boolean => {
    return !!pendingSettingsRef.current && pendingEntityIdRef.current === forEntityId;
  }, []);

  // Cancel pending debounce timeout
  const cancelPendingSave = useCallback(() => {
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = null;
    }
  }, []);

  // Clear pending refs and cancel timeout (for revert/reset)
  const clearPending = useCallback(() => {
    pendingSettingsRef.current = null;
    pendingEntityIdRef.current = null;
    cancelPendingSave();
  }, [cancelPendingSave]);

  // Schedule a debounced save
  // Uses statusRef instead of status to avoid recreating on every status transition.
  // The status check is a guard ("don't save while loading") — reading the latest
  // value at call time via ref is more correct than capturing it at creation time.
  const scheduleSave = useCallback((_forEntityId: string | null) => {
    // During loading, don't schedule saves - just let pending tracking do its work
    const currentStatus = statusRef.current;
    if (currentStatus !== 'ready' && currentStatus !== 'saving') {
      return;
    }

    cancelPendingSave();

    const timeoutId = setTimeout(async () => {
      try {
        // Get the LATEST settings at save time (not a captured value which could be stale)
        const latestSettings = await getLatestSettings();
        await saveImmediateRef.current(latestSettings);

        // Only clear pending when the saved payload still matches the latest tracked input.
        // If the user typed again during the async save, pendingSettingsRef now points to
        // newer data and must be preserved for the next explicit flush.
        if (
          pendingEntityIdRef.current === _forEntityId &&
          pendingSettingsRef.current &&
          deepEqual(pendingSettingsRef.current, latestSettings)
        ) {
          pendingSettingsRef.current = null;
          pendingEntityIdRef.current = null;
        }
      } catch (err) {
        normalizeAndPresentError(err, { context: 'useDebouncedSettingsSave.debouncedSave', showToast: false });
      }
    }, debounceMs);
    saveTimeoutRef.current = timeoutId;
  }, [debounceMs, cancelPendingSave, getLatestSettings, saveImmediateRef]);

  /**
   * Fire-and-forget flush of pending settings to DB.
   * Used by both entity-change cleanup and beforeunload handlers.
   */
  const flushPendingSettings = useCallback((
    pending: T,
    pendingForEntity: string,
    flushScope: 'shot' | 'project',
    flushToolId: string,
    flushIsCustomMode: boolean,
    customSave: ((entityId: string, data: T) => Promise<void>) | undefined,
    onFlush: ((entityId: string, data: T) => void) | undefined,
    context: string,
  ) => {
    if (flushIsCustomMode) {
      if (customSave) {
        customSave(pendingForEntity, pending)
          .then(() => { onFlush?.(pendingForEntity, pending); })
          .catch(err => { normalizeAndPresentError(err, { context, showToast: false }); });
      }
    } else {
      updateToolSettingsSupabase({
        scope: flushScope,
        id: pendingForEntity,
        toolId: flushToolId,
        patch: pending,
      }, { mode: 'immediate' })
        .then(() => {
          const cacheKey = flushScope === 'shot'
            ? queryKeys.settings.tool(flushToolId, projectId ?? undefined, pendingForEntity)
            : queryKeys.settings.tool(flushToolId, pendingForEntity, undefined);
          queryClient.invalidateQueries({ queryKey: cacheKey });
          if (flushScope === 'shot' && pendingForEntity) {
            queryClient.refetchQueries({ queryKey: queryKeys.shots.batchSettings(pendingForEntity) });
          }
        })
        .catch(err => { normalizeAndPresentError(err, { context, showToast: false }); });
    }
  }, [projectId, queryClient]);

  // Flush pending settings on entity change/unmount
  useEffect(() => {
    const currentEntityId = entityId;
    const currentScope = scope;
    const currentToolId = toolId;
    const currentIsCustomMode = isCustomMode;
    const customSave = customSaveRef.current;
    const onFlush = onFlushRef.current;

    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
        saveTimeoutRef.current = null;
      }

      const pending = pendingSettingsRef.current;
      const pendingForEntity = pendingEntityIdRef.current;

      if (pending && pendingForEntity && pendingForEntity === currentEntityId) {
        flushPendingSettings(
          pending, pendingForEntity, currentScope, currentToolId,
          currentIsCustomMode, customSave, onFlush,
          'useDebouncedSettingsSave.cleanupFlush',
        );
      }

      if (pendingForEntity === currentEntityId) {
        pendingSettingsRef.current = null;
        pendingEntityIdRef.current = null;
      }
    };
  }, [entityId, scope, toolId, isCustomMode, projectId, queryClient, customSaveRef, onFlushRef, flushPendingSettings]);

  // Flush on page close/navigation (best-effort, ~50-100ms budget)
  useEffect(() => {
    const customSave = customSaveRef.current;

    const handleBeforeUnload = () => {
      const pending = pendingSettingsRef.current;
      const pendingForEntity = pendingEntityIdRef.current;
      if (pending && pendingForEntity) {
        flushPendingSettings(
          pending, pendingForEntity, scope, toolId,
          isCustomMode, customSave, undefined,
          'useDebouncedSettingsSave.unloadFlush',
        );
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [toolId, scope, isCustomMode, customSaveRef, flushPendingSettings]);

  // Memoize return to prevent object recreation on every render.
  // Without this, every effect/callback depending on `debouncedSave` would re-run
  // on every render, cascading re-renders through the entire settings tree.
  return useMemo(() => ({
    scheduleSave,
    cancelPendingSave,
    clearPending,
    trackPendingUpdate,
    hasPendingFor,
    pendingSettingsRef,
    pendingEntityIdRef,
    saveTimeoutRef,
  }), [scheduleSave, cancelPendingSave, clearPending, trackPendingUpdate, hasPendingFor]);
}

