        "retro-dark": "rounded-sm border-2 border-[#6a7a7a] bg-[#3a4a4a] text-[#d8d4cb] shadow-[-3px_3px_0_0_rgba(20,30,30,0.3)]",
        // Zinc variant for dark panes
